// Every link on this page is built by `hrefWith` from the WHOLE state: no gate can see a dropped query
// parameter, so dropping one has to be a visible act rather than an omission.

import { folderFor, folderRank } from "./folders.mjs";
import { suggestedAlt } from "./usage.mjs";

export const VIEWS = ["list", "grid"];

export const GROUPS = ["flat", "folder", "month"];

export const SORTS = ["added", "name", "size", "usage"];

export const DIRS = ["desc", "asc"];

/**
 * A sort key carries its direction: "Largest" ascending would list the smallest. The Display popover and
 * the list header both read this, so they produce the same URL for the same column.
 *
 * @type {Record<string, string>}
 */
const SORT_DEFAULT_DIR = {
  added: "desc",
  name: "asc",
  size: "desc",
  usage: "asc",
};

export const SIZES = ["s", "m", "l"];

// `all` is the absence of a lens, so it is not a member.
const LENSES = ["unattached", "duplicates", "no-alt", "large"];

const CONFIRMS = ["empty-trash"];

// LIST by default: most rows are PDFs, which a grid renders as empty boxes.
export const DEFAULTS = {
  view: "list",
  // Folder by default: the section note is what says why a file exists.
  group: "folder",
  sort: "added",
  dir: "desc",
  size: "m",
  role: "content",
  q: "",
  tag: "",
  lens: "",
  page: 1,
  trash: false,
  // In the state, so an open inspector survives a sort change.
  key: "",
  // A URL, not `prompt()`, so the confirmation works with scripting off. With no script a `prompt()`
  // handler never runs and the form deletes straight through.
  confirm: "",
};

export const PARAM_NAMES = Object.keys(DEFAULTS);

/** @param {unknown} value @param {string[]} allowed @param {string} fallback */
function oneOf(value, allowed, fallback) {
  return typeof value === "string" && allowed.includes(value) ? value : fallback;
}


/**
 * Total: an unrecognized value falls back to its default, so a hand-edited URL still shows a library.
 *
 * @param {{ get(name: string): string | null }} params
 * @returns {typeof DEFAULTS}
 */
export function readView(params) {
  const page = Number(params.get("page") ?? "1");
  return {
    view: oneOf(params.get("view"), VIEWS, DEFAULTS.view),
    group: oneOf(params.get("group"), GROUPS, DEFAULTS.group),
    sort: oneOf(params.get("sort"), SORTS, DEFAULTS.sort),
    dir: oneOf(params.get("dir"), DIRS, DEFAULTS.dir),
    size: oneOf(params.get("size"), SIZES, DEFAULTS.size),
    // `all` asks for every role; an ABSENT role means the default, `content`.
    role: typeof params.get("role") === "string" && params.get("role") !== ""
      ? /** @type {string} */ (params.get("role"))
      : DEFAULTS.role,
    q: (params.get("q") ?? "").trim(),
    tag: (params.get("tag") ?? "").trim().toLowerCase(),
    lens: oneOf(params.get("lens"), LENSES, DEFAULTS.lens),
    page: Number.isFinite(page) && page >= 1 ? Math.floor(page) : 1,
    trash: params.get("trash") === "1",
    // Not trimmed or lowercased: a key is an exact string, and many are paths.
    key: params.get("key") ?? "",
    confirm: oneOf(params.get("confirm"), CONFIRMS, DEFAULTS.confirm),
  };
}

/**
 * The only way a link on this page should be built. Defaults are omitted, so the bare URL is the
 * default view and `Reset to defaults` can link to it.
 *
 * @param {typeof DEFAULTS} state
 * @param {Partial<typeof DEFAULTS>} [overrides]
 * @param {string} [base]
 * @returns {string}
 */
export function hrefWith(state, overrides = {}, base = "/admin/media") {
  const next = { ...state, ...overrides };
  const search = new URLSearchParams();
  for (const name of PARAM_NAMES) {
    const value = /** @type {any} */ (next)[name];
    const fallback = /** @type {any} */ (DEFAULTS)[name];
    if (value === fallback) continue;
    if (name === "trash") {
      if (value) search.set("trash", "1");
      continue;
    }
    if (name === "page") {
      if (Number(value) > 1) search.set("page", String(value));
      continue;
    }
    if (value === "" || value === null || value === undefined) continue;
    search.set(name, String(value));
  }
  const query = search.toString();
  return query ? `${base}?${query}` : base;
}

/**
 * `page` is excluded: it is navigation, not a setting.
 *
 * @param {typeof DEFAULTS} state
 * @returns {boolean}
 */
export function isModified(state) {
  return PARAM_NAMES.filter((n) => n !== "page").some(
    (n) => /** @type {any} */ (state)[n] !== /** @type {any} */ (DEFAULTS)[n],
  );
}

/**
 * PAGE-LOCAL, always: a group never spans a page boundary. Do not "fix" this; fetching the whole
 * library or repeating a heading across pages are both worse. The SQL order is preserved.
 *
 * @template {{ key: string, uploaded?: string | null }} T
 * @param {T[]} rows already sorted
 * @param {string} group one of GROUPS
 * @returns {Array<{ label: string, note: string, rows: T[] }>} one entry when flat
 */
export function groupRows(rows, group) {
  if (group !== "folder" && group !== "month") return [{ label: "", note: "", rows }];

  /** @type {Map<string, T[]>} */
  const buckets = new Map();
  for (const row of rows) {
    const label = group === "folder" ? folderFor(row.key).prefix : monthOf(row.uploaded);
    const bucket = buckets.get(label);
    if (bucket) bucket.push(row);
    else buckets.set(label, [row]);
  }

  const out = [...buckets.entries()].map(([label, bucketRows]) => {
    if (group !== "folder") return { label, note: "", rows: bucketRows };
    // The note travels with the section, so the component cannot forget to render it.
    const folder = folderFor(bucketRows[0]?.key ?? "");
    return { label: folder.title, note: folder.note, rows: bucketRows };
  });

  // Folder sections follow the table's order; month grouping keeps first-row order, since there the
  // sort is the meaning.
  if (group !== "folder") return out;
  return out.sort(
    (a, b) =>
      folderRank(folderFor(a.rows[0]?.key ?? "").prefix) -
      folderRank(folderFor(b.rows[0]?.key ?? "").prefix),
  );
}

/**
 * @param {string} key
 * @returns {string}
 */
export function folderOf(key) {
  const at = key.lastIndexOf("/");
  if (at <= 0) return "Uploads";
  return key.slice(0, at);
}

/**
 * UTC, so a heading does not move with the reader's timezone.
 *
 * @param {string | null | undefined} uploaded ISO 8601
 * @returns {string}
 */
export function monthOf(uploaded) {
  const d = utcDate(uploaded);
  if (!d) return "No upload date";
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

/**
 * The one parse, so the month heading and the Added cell under it cannot disagree about a date.
 *
 * @param {string | null | undefined} uploaded ISO 8601
 * @returns {Date | null} null when absent or unparseable
 */
function utcDate(uploaded) {
  if (!uploaded) return null;
  const at = Date.parse(uploaded);
  return Number.isNaN(at) ? null : new Date(at);
}

// Abbreviations are derived: all twelve are the first three letters (test/media-view-dates.test.mjs).
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

const MONTH_ABBR = MONTHS.map((m) => m.slice(0, 3));

/**
 * UTC, matching the month heading above it. Reads no clock.
 *
 * @param {string | null | undefined} uploaded ISO 8601
 * @returns {string}
 */
export function formatAdded(uploaded) {
  const d = utcDate(uploaded);
  if (!d) return "in repo";
  return `${String(d.getUTCDate()).padStart(2, "0")} ${MONTH_ABBR[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

/**
 * No em dash allowed here, so an unmeasured row says so in words; 0x0 would be a claim.
 *
 * @param {number | null | undefined} width
 * @param {number | null | undefined} height
 * @returns {string}
 */
export function formatDims(width, height) {
  return width && height ? `${width}×${height}` : "not measured";
}

/**
 * Empty for a content-addressed key: unlike `folderOf`, which names a heading, it invents no folder.
 *
 * @param {string} key
 * @returns {string}
 */
export function folderPrefix(key) {
  const at = key.lastIndexOf("/");
  return at > 0 ? `${key.slice(0, at)}/` : "";
}

/**
 * The last segment: the roster photos share their directory and differ only at the end.
 *
 * @param {{ originalName: string | null, key: string }} object
 * @returns {string}
 */
export function displayName(object) {
  if (object.originalName) return object.originalName;
  const last = object.key.split("/").pop();
  return last && last.length > 0 ? last : object.key;
}

/**
 * From the middle: these names differ at the end (`...session-01`, `...session-02`). The cap is 13
 * because the name gets 109px on a 153px tile (measured; 14 clipped by a pixel). Characters, not
 * pixels, because the server cannot measure a font; the CSS ellipsis is the backstop.
 *
 * @param {string} name
 * @param {number} [max]
 * @param {number} [tail]
 * @returns {string}
 */
export function middleTruncate(name, max = 13, tail = 9) {
  if (name.length <= max) return name;
  return `${name.slice(0, max - tail - 1)}…${name.slice(-tail)}`;
}

/**
 * Shared by the Display popover and the column headers so both produce one URL. Only the active column
 * toggles. Always back to page one: page 3 of one sort is not page 3 of another.
 *
 * @param {typeof DEFAULTS} state
 * @param {string} key one of SORTS
 * @param {{ toggle?: boolean }} [options] toggle when the key is already active
 * @returns {string}
 */
export function sortHref(state, key, options = {}) {
  const active = state.sort === key;
  const dir =
    options.toggle && active
      ? state.dir === "asc"
        ? "desc"
        : "asc"
      : SORT_DEFAULT_DIR[key] ?? DEFAULTS.dir;
  return hrefWith(state, { sort: key, dir, page: 1 });
}

/**
 * A document card's title: the filename read as words, the same reading the alt suggestion makes.
 * Not capitalized: title-casing a filename means guessing which words are proper nouns.
 */
export const docTitle = suggestedAlt;

/**
 * @param {typeof DEFAULTS} state
 * @returns {string}
 */
export function displaySummary(state) {
  const group = { flat: "Flat", folder: "Folder", month: "Month" }[state.group];
  const sort = { added: "Newest", name: "A to Z", size: "Largest", usage: "Usage" }[state.sort];
  return [group, sort, state.size.toUpperCase()].join(" · ");
}

// These never reach SQL, so a change skips the server (test/media-display-axes.test.mjs). `sort` and
// `dir` must NOT be added: the page paginates, so reordering changes which rows page one holds.
const DISPLAY_AXES = ["view", "group", "size"];

/**
 * Overlaid on the loader's view so a display change renders from the client URL with no revalidation.
 *
 * @param {{ get(name: string): string | null }} params
 * @returns {{ view: string, group: string, size: string }}
 */
export function readDisplayAxes(params) {
  return {
    view: oneOf(params.get("view"), VIEWS, DEFAULTS.view),
    group: oneOf(params.get("group"), GROUPS, DEFAULTS.group),
    size: oneOf(params.get("size"), SIZES, DEFAULTS.size),
  };
}

/**
 * Identical URLs return FALSE: a post-action revalidation has the same URL on both sides, and skipping
 * it would hide the write.
 *
 * @param {URL} currentUrl
 * @param {URL} nextUrl
 * @returns {boolean}
 */
export function onlyDisplayChanged(currentUrl, nextUrl) {
  if (currentUrl.pathname !== nextUrl.pathname) return false;

  const a = currentUrl.searchParams;
  const b = nextUrl.searchParams;

  // Compared through `readView` so `?view=list` and the bare URL count as the same state.
  const from = readView(a);
  const to = readView(b);
  const names = /** @type {(keyof typeof from)[]} */ (PARAM_NAMES);
  for (const name of names) {
    if (DISPLAY_AXES.includes(name)) continue;
    if (from[name] !== to[name]) return false;
  }

  return /** @type {(keyof typeof from)[]} */ (DISPLAY_AXES).some(
    (name) => from[name] !== to[name],
  );
}

app/lib/pages/compile.mjs.source:
// One door from a page file to everything derived from it: parse, validate, render, the markdown twin and
// the search input. build:content, sync:content and the adapter's page save all call compilePage, so
// a file CI passes is the file the save tool accepts and the page draws (docs/PAGES.md).

import matter from "gray-matter";

import { gitBlobSha } from "../content/hashes.mjs";
import {
  CONTENT_PAGE_SECTIONS,
  DESCRIPTION_MAX,
  LEGAL_BANNER,
  LEGAL_PAGE_PATHS,
  PAGE_FILE_PATHS,
  SEO_TITLE_MAX,
  contentPageFile,
  contentPageMarkdownBody,
  contentPageSearchInputs,
  markdownTableFacts,
} from "../content-pages.mjs";
import { IDENTITY } from "../identity.generated.mjs";
import { expandPhagePage, expandPhageTokens } from "../phages/compile.mjs";
import { pageInvariantErrors } from "./invariants.mjs";
import { protectedPageReason } from "./protected.mjs";

export const PAGES_DIR = "content/pages";

/** The identity facts a page may state by token ({{identity.role}}): text, from the CV (app/lib/identity.mjs). */
export const IDENTITY_TOKEN_KEYS = /** @type {const} */ ([
  "name", "degree", "discipline", "disciplineLower", "rank", "role", "adminTitle", "jobTitle", "cvTitle", "department", "departmentSubject", "affiliation",
]);
const IDENTITY_TOKEN = /\{\{\s*identity\.([A-Za-z]+)\s*\}\}/g;

/**
 * Every token a page can carry, filled: the owner's identity from the CV, then the phage facts from the rows. A
 * title, a role or a headship a page states is read, never typed, so a CV change updates the page. A token that
 * names nothing is an error, never an empty string.
 *
 * @param {string} text
 * @param {import("../phages/compile.mjs").Phage[] | undefined} phages
 * @returns {{ ok: true, text: string } | { ok: false, errors: string[] }}
 */
export function expandPageTokens(text, phages) {
  /** @type {string[]} */
  const errors = [];
  const withIdentity = text.replace(IDENTITY_TOKEN, (whole, key) => {
    if (!(/** @type {readonly string[]} */ (IDENTITY_TOKEN_KEYS).includes(key))) {
      errors.push(`${whole} is not an identity fact (${IDENTITY_TOKEN_KEYS.join(", ")})`);
      return whole;
    }
    return String(/** @type {Record<string, unknown>} */ (IDENTITY)[key]);
  });
  if (errors.length > 0) return { ok: false, errors };
  return expandPhageTokens(withIdentity, phages);
}

/** The repository path of a page's file, from its file key (`research-phages`). */
export function pageSourcePath(/** @type {string} */ slug) {
  return `${PAGES_DIR}/${slug}.md`;
}

/** The file key of a registered path: `/research/phages` is `research-phages`. */
export function pageSlug(/** @type {string} */ path) {
  return contentPageFile(path).slice(0, -3);
}

/** The registered path a file key stands for, or undefined when no page file may have that key. */
export function pagePathForSlug(/** @type {string} */ slug) {
  return PAGE_FILE_PATHS.find((path) => pageSlug(path) === slug);
}

/** The schema.org types a page may declare; app/routes/content-page.tsx shapes a node for each. */
const SCHEMA_TYPES = ["SoftwareApplication", "SoftwareSourceCode", "WebSite", "WebPage", "Dataset"];

/**
 * @typedef {{
 *   schemaType?: string,
 *   productUrl?: string,
 *   codeRepository?: string,
 *   applicationCategory?: string,
 *   license?: string,
 *   programmingLanguage?: string,
 *   runtimePlatform?: string,
 *   spatialCoverage?: string,
 *   dataset?: { variableMeasured: string[], temporalCoverage: string | null, rows: number },
 * }} PageSchema
 *
 * What only a legal page states (LEGAL_PAGE_PATHS): `banner` is the one word "Draft", `lastUpdated` an ISO date.
 * @typedef {{ banner?: string, lastUpdated?: string }} PageLegal
 *
 * @typedef {{ depth: number, id: string, text: string }} TocEntry
 *
 * The page as the routes, the search index and the gates read it. `markdown` is the body without front
 * matter; the twin a machine reads is built from it (contentPageMarkdownBody).
 * @typedef {{
 *   path: string, title: string, seoTitle: string, description: string, html: string,
 *   markdown: string, toc: TocEntry[],
 * } & PageSchema & PageLegal} CompiledPage
 *
 * What D1's `record` column holds: the page less its markdown, with its file key and draft flag.
 * @typedef {Omit<CompiledPage, "markdown"> & { slug: string, draft: boolean }} PageRecord
 */

/**
 * The structured-data facts a page's front matter states, each only when it is written there: the JSON-LD
 * says what the page holds and never fills a gap. A Dataset also carries what its first table says.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} markdown
 * @param {string[]} errors
 * @returns {PageSchema}
 */
function pageSchema(fm, markdown, errors) {
  const text = (/** @type {unknown} */ value) => (value == null || value === "" ? "" : String(value));
  const schemaType = text(fm.schema_type);
  if (schemaType && !SCHEMA_TYPES.includes(schemaType)) {
    errors.push(`schema_type "${schemaType}" is not one of ${SCHEMA_TYPES.join(", ")}`);
  }
  const codeRepository = text(fm.code_repository);
  if (codeRepository && !["SoftwareApplication", "SoftwareSourceCode"].includes(schemaType)) {
    errors.push("code_repository is only stated for software (schema_type SoftwareApplication or SoftwareSourceCode)");
  }
  const dataset = schemaType === "Dataset" ? markdownTableFacts(markdown) : null;
  if (schemaType === "Dataset" && !dataset) {
    errors.push("schema_type is Dataset but the page has no markdown table for it to describe");
  }
  /** @type {Array<[Exclude<keyof PageSchema, "dataset">, string]>} */
  const fields = [
    ["schemaType", schemaType],
    ["productUrl", text(fm.product_url)],
    ["codeRepository", codeRepository],
    ["applicationCategory", text(fm.application_category)],
    ["license", text(fm.license)],
    ["programmingLanguage", text(fm.programming_language)],
    ["runtimePlatform", text(fm.runtime_platform)],
    ["spatialCoverage", text(fm.spatial_coverage)],
  ];
  /** @type {PageSchema} */
  const schema = dataset ? { dataset } : {};
  for (const [key, value] of fields) if (value !== "") schema[key] = value;
  return schema;
}

/**
 * The banner and the last-updated date a legal page states, each only when it is written there. The banner is
 * the single word "Draft" and nothing else; the date is a real calendar day. Neither belongs on any other page.
 * YAML reads an unquoted `2026-10-06` as a Date and rolls an impossible `2026-02-30` over to March, so the
 * day is read from the front matter's own text, the way it was written, and the parsed value only when the
 * line cannot be found.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} frontMatter the front matter's text, as written
 * @param {string} path
 * @param {string[]} errors
 * @returns {PageLegal}
 */
function pageLegal(fm, frontMatter, path, errors) {
  /** @type {PageLegal} */
  const legal = {};
  const banner = fm.banner == null ? "" : String(fm.banner).trim();
  if (banner !== "") {
    if (banner !== LEGAL_BANNER) errors.push(`banner is ${JSON.stringify(banner)}; the one word it may say is "${LEGAL_BANNER}"`);
    else legal.banner = banner;
  }
  const written = /^last_updated:[ \t]*["']?([^"'#\r\n]*?)["']?[ \t]*(?:#.*)?$/m.exec(frontMatter)?.[1];
  const raw = written ?? fm.last_updated;
  if (raw != null && raw !== "") {
    const day = raw instanceof Date ? raw.toISOString().slice(0, 10) : String(raw).trim();
    const real = /^\d{4}-\d{2}-\d{2}$/.test(day) && new Date(`${day}T00:00:00.000Z`).toISOString().slice(0, 10) === day;
    if (real) legal.lastUpdated = day;
    else errors.push(`last_updated is ${JSON.stringify(day)}; it is a real day written YYYY-MM-DD`);
  }
  if ((legal.banner || legal.lastUpdated || fm.banner != null || fm.last_updated != null) && !LEGAL_PAGE_PATHS.includes(path)) {
    errors.push(`banner and last_updated belong to the legal pages (${LEGAL_PAGE_PATHS.join(", ")}), not to ${path}`);
  }
  return legal;
}

/**
 * The page's dictionary entry (docs/DICTIONARY.md), when it has a published one, leads its twin and its search
 * record, so `entry` is the caller's to give: the build reads it from content/dictionary, the Worker from D1.
 *
 * @param {{
 *   slug: string,
 *   raw: string,
 *   pipeline: { renderBody: (input: { file: string, body: string, resolveImage: (src: string) => Promise<never> }) => Promise<{ html: string, toc: TocEntry[], blockedUrls: Array<{ url: string }> }>,
 *               findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> },
 *   sourcePath?: string,
 *   generated?: boolean,
 *   entry?: import("../dictionary-entries.mjs").DictionaryEntry,
 *   phages?: import("../phages/compile.mjs").Phage[],
 * }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], page: CompiledPage, record: PageRecord, draft: boolean, markdown: string,
 *       searchInput: ReturnType<typeof contentPageSearchInputs>[number], sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePage({ slug, raw, pipeline, sourcePath, generated = false, entry, phages }) {
  const expectedPath = pagePathForSlug(slug);
  if (!expectedPath) {
    return {
      ok: false,
      errors: [
        `"${slug}" is not a registered page. A page's address is structure: add the path to CONTENT_PAGE_PATHS ` +
          "(app/lib/content-pages.mjs) in code, and a save can then write its file; a save cannot create a new path",
      ],
    };
  }
  const file = sourcePath ?? pageSourcePath(slug);
  /** @type {string[]} */
  const errors = (generated ? [] : pipeline.findWideDashes(raw)).map((hit) => `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`);

  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return { ok: false, errors: [...errors, `the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`] };
  }
  const fm = /** @type {Record<string, unknown>} */ (parsed.data);
  // A phage fact a page states (the count, the span, a genome's size) is read from the phage rows by a token,
  // never typed, so the title and description fill the same way the body does.
  /** @param {unknown} value @returns {string} */
  const filled = (value) => {
    const result = expandPageTokens(String(value ?? ""), phages);
    if (!result.ok) {
      errors.push(...result.errors);
      return String(value ?? "");
    }
    return result.text;
  };
  const page = {
    path: String(fm.path ?? ""),
    title: filled(fm.title),
    seoTitle: filled(fm.seo_title),
    description: filled(fm.description),
  };
  if (page.path !== expectedPath) {
    errors.push(
      `path is "${page.path}", but ${contentPageFile(expectedPath)} is the file for ${expectedPath}: every page ` +
        "must be listed in CONTENT_PAGE_PATHS (app/lib/content-pages.mjs) and its file must say so",
    );
  }
  for (const [field, value] of [["title", page.title], ["seo_title", page.seoTitle], ["description", page.description]]) {
    if (!value) errors.push(`${field} is required`);
  }
  if (page.seoTitle.length > SEO_TITLE_MAX) {
    errors.push(`seo_title is ${page.seoTitle.length} characters (at most ${SEO_TITLE_MAX}); Google would clip it`);
  }
  if (page.description.length > DESCRIPTION_MAX) {
    errors.push(`description is ${page.description.length} characters (at most ${DESCRIPTION_MAX}); Google would clip it`);
  }
  if (fm.draft !== undefined && typeof fm.draft !== "boolean") {
    errors.push(`draft is ${JSON.stringify(fm.draft)}; it is true or false`);
  }
  // The phage page's table and sections are drawn from the phage rows where the file's markers say
  // (docs/PHAGES.md), before anything reads the body, so its HTML, twin, dataset facts and search record all come
  // from one text. Every other page passes through unchanged.
  const drawn = expandPhagePage(page.path, parsed.content, phages);
  if (!drawn.ok) errors.push(...drawn.errors);
  const drawnBody = drawn.ok ? expandPageTokens(drawn.markdown, phages) : /** @type {const} */ ({ ok: true, text: parsed.content });
  if (!drawnBody.ok) errors.push(...drawnBody.errors);
  const body = drawnBody.ok ? drawnBody.text : parsed.content;
  const schema = pageSchema(fm, body, errors);
  const legal = pageLegal(fm, parsed.matter, page.path, errors);
  const keep = protectedPageReason(page.path);
  if (keep && fm.draft === true) errors.push(`draft is true, but ${keep}`);
  if (errors.length > 0) return { ok: false, errors };

  let rendered;
  try {
    rendered = await pipeline.renderBody({
      file,
      body,
      resolveImage: async (src) => {
        throw new Error(`the page references an image ("${src}") and these pages have no image pipeline`);
      },
    });
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : String(error)] };
  }
  if (rendered.blockedUrls.length > 0) {
    errors.push(`links the URL allowlist refused: ${rendered.blockedUrls.map((b) => b.url).join(", ")}`);
  }
  for (const section of CONTENT_PAGE_SECTIONS) {
    const [sectionPath, id] = section.split("#");
    if (sectionPath === page.path && !rendered.toc.some((heading) => heading.id === id)) {
      errors.push(`no heading has the id "${id}", which CONTENT_PAGE_SECTIONS (app/lib/content-pages.mjs) lists for the header menu`);
    }
  }

  /** @type {CompiledPage} */
  const compiled = { ...page, html: rendered.html, markdown: body, toc: rendered.toc, ...schema, ...legal };
  errors.push(...pageInvariantErrors(compiled, { phages }));
  if (errors.length > 0) return { ok: false, errors };

  const draft = fm.draft === true;
  const { markdown: _body, ...rest } = compiled;
  const [searchInput] = contentPageSearchInputs([compiled], () => entry);
  if (!searchInput) throw new Error(`no search input was made for ${page.path}`);
  return {
    ok: true,
    errors: [],
    page: compiled,
    record: { slug, draft, ...rest },
    draft,
    markdown: contentPageMarkdownBody(compiled, entry),
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/lib/podcast/feed.mjs.source:
// Pure, so node:test and the CSP builder can import it. Every feed URL is checked against a host
// allowlist; the audio list is what workers/csp.mjs writes into `media-src`, so the two cannot disagree.

import { decodeEntities } from "../publications/entities.mjs";

export const PODCAST_FEED_URL = "https://germomics.com/feed/podcast/";

export const PODCAST_SITE_URL = "https://germomics.com/";

// `op3.dev` is the feed's analytics prefix and 302s to `media.germomics.com`; CSP checks the redirect
// target too, so both are listed.
export const PODCAST_AUDIO_HOSTS = ["op3.dev", "media.germomics.com"];

const EPISODE_PAGE_HOSTS = ["germomics.com", "www.germomics.com"];

/**
 * @typedef {{
 *   guid: string,
 *   title: string,
 *   link: string,
 *   publishedAt: string,
 *   durationSeconds: number | null,
 *   description: string,
 *   audioUrl: string,
 *   audioType: string,
 *   season: number | null,
 *   episode: number | null,
 * }} PodcastEpisode
 */

/**
 * The shared decoder, plus `&nbsp;`: podcast hosts write it in show notes, and every whitespace run
 * here collapses to one space anyway. Replaced before decoding, so `&amp;nbsp;` still reads literally.
 *
 * @param {string} text
 */
function decodeFeedEntities(text) {
  return decodeEntities(text.replace(/&nbsp;/g, " "));
}

/**
 * @param {string} xml @param {string} tag
 */
function textOf(xml, tag) {
  const escaped = tag.replace(":", "\\:");
  const match = xml.match(new RegExp(`<${escaped}(?:\\s[^>]*)?>([\\s\\S]*?)</${escaped}>`));
  if (!match) return "";
  const raw = (match[1] ?? "").replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1");
  return decodeFeedEntities(raw.replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
}

/** @param {string} xml @param {string} tag @param {string} attr */
function attrOf(xml, tag, attr) {
  const element = xml.match(new RegExp(`<${tag.replace(":", "\\:")}\\s[^>]*>`));
  if (!element) return "";
  const value = element[0].match(new RegExp(`\\s${attr}="([^"]*)"`));
  return value ? decodeFeedEntities(value[1] ?? "") : "";
}

/**
 * @param {string} value @param {readonly string[]} hosts
 */
function allowedHttpsUrl(value, hosts) {
  try {
    const url = new URL(value);
    if (url.protocol !== "https:" || url.username || url.password || url.port) return null;
    return hosts.includes(url.hostname) ? url.href : null;
  } catch {
    return null;
  }
}

/**
 * @param {string} value
 */
export function parseDuration(value) {
  if (!/^\d+(:\d{1,2}){0,2}$/.test(value)) return null;
  return value.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}

/** @param {string} value */
function positiveInt(value) {
  return /^\d+$/.test(value) && Number(value) > 0 ? Number(value) : null;
}

/**
 * @param {string} xml
 * @returns {PodcastEpisode[]}
 */
export function parsePodcastFeed(xml) {
  /** @type {PodcastEpisode[]} */
  const episodes = [];
  for (const [, item = ""] of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
    const title = textOf(item, "title");
    const guid = textOf(item, "guid");
    const link = allowedHttpsUrl(textOf(item, "link"), EPISODE_PAGE_HOSTS);
    const audioUrl = allowedHttpsUrl(attrOf(item, "enclosure", "url"), PODCAST_AUDIO_HOSTS);
    const audioType = attrOf(item, "enclosure", "type");
    const published = new Date(textOf(item, "pubDate"));
    if (!title || !guid || !link || !audioUrl || !audioType.startsWith("audio/")) continue;
    if (Number.isNaN(published.getTime())) continue;
    episodes.push({
      guid,
      title,
      link,
      publishedAt: published.toISOString(),
      durationSeconds: parseDuration(textOf(item, "itunes:duration")),
      description: textOf(item, "description"),
      audioUrl,
      audioType,
      season: positiveInt(textOf(item, "itunes:season")),
      episode: positiveInt(textOf(item, "itunes:episode")),
    });
  }
  return episodes.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
}

app/lib/publications/listing.mjs.source:
/**
 * The publication index (docs/PUBLICATIONS.md): its fields declared once for Capsomer's catalog, so the search box, the
 * topic and other facets, the sort menu, the year headings and the counts all come from this one declaration. Pure
 * over the query string and the papers it is handed. The route adds the citation counts (a D1 read) and the page copy.
 *
 * What did not change, because search engines and the machine-readable gates hold it: `?topic=` is the address of a
 * topic's papers, and exactly the four bare single-topic addresses canonicalise to themselves (`soleTopic`); every other
 * address is a view of the base page.
 */

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { decodeEntities } from "./entities.mjs";
import { TOPICS, TOPIC_IDS } from "./topics.mjs";

/** @typedef {import("./types.ts").Publication} Publication */
/** @typedef {import("./types.ts").PublicationType} PublicationType */
/** @typedef {import("./types.ts").TopicId} TopicId */

/**
 * Conference abstracts stay in the data file, which the CV also reads, and are excluded here.
 *
 * @type {Set<PublicationType>}
 */
export const SHOWCASE_TYPES = new Set([
  "article",
  "review",
  "chapter",
  "teaching-resource",
]);

const PUBLICATIONS_BASE = "/research/publications";

const TYPE_LABELS = /** @type {Record<string, string>} */ ({
  article: "Article",
  review: "Review",
  chapter: "Chapter",
  "teaching-resource": "Teaching resource",
});

/** The journal, volume and pages as the page prints them, entities decoded (the year has its own column). @param {Publication} p */
export function venue(p) {
  return decodeEntities([p.journal, p.volume, p.pages].filter(Boolean).join(", "));
}

/** The papers' catalog. Newest first by default, under a heading for each year; any search or other sort is flat. */
export const PUBLICATIONS = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Publication>} */ ({
    id: "papers",
    noun: ["paper", "papers"],
    basePath: PUBLICATIONS_BASE,
    itemKey: (p) => p.id,
    defaultSort: "-year",
    group: { field: "year" },
    fields: [
      { key: "title", label: "Title", value: (p) => decodeEntities(p.title), search: 3, sort: true, column: { header: "Paper" } },
      { key: "authors", label: "Authors", value: (p) => p.authors.map(decodeEntities), search: 1 },
      { key: "journal", label: "Journal", value: (p) => venue(p), search: 2, column: { header: "Journal", drop: 1 } },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { labels: { asc: "oldest first", desc: "newest first" } },
        column: { header: "Year", align: "end", hideWhenGrouped: true },
      },
      {
        key: "topic",
        label: "Topic",
        value: (p) => p.topics,
        facet: { kind: "many", general: true, order: TOPICS.map((t) => t.id), label: (v) => TOPICS.find((t) => t.id === v)?.label ?? v },
      },
      { key: "type", label: "Type", value: (p) => p.type, facet: { kind: "many", label: (v) => TYPE_LABELS[v] ?? v } },
      // Chosen with `?selected=1`, as the page's "Selected" filter always was.
      { key: "selected", label: "Selected", value: (p) => (p.selected ? "1" : null), facet: { kind: "one", label: () => "Selected papers" } },
      { key: "access", label: "Access", value: (p) => (p.isOpenAccess ? "open" : null), facet: { kind: "one", label: () => "Open access" } },
    ],
  }),
);

/**
 * The address a request written in the old parameters should have, or null. The page used `?sort=year-desc|year-asc|title`
 * and `?selected=1|true`; the catalog says `sort=-year|year|title` and `selected=1`. A link in the wild keeps working: it
 * is sent, once, to the same view at its new address. A request with none of the old spellings is left alone.
 *
 * @param {URL} url
 */
export function legacyAddress(url) {
  const params = url.searchParams;
  const sort = params.get("sort");
  const oldSort = sort === "year-desc" || sort === "year-asc";
  const oldSelected = (params.get("selected") ?? "").toLowerCase() === "true";
  if (!oldSort && !oldSelected) return null;
  const next = new URLSearchParams(params);
  if (sort === "year-desc") next.delete("sort");
  if (sort === "year-asc") next.set("sort", "year");
  if (oldSelected) next.set("selected", "1");
  return queryCatalog(PUBLICATIONS, [], parseCatalogParams(PUBLICATIONS, next)).href();
}

/**
 * Only the four bare single-topic URLs self-canonical: the rest are subsets or orderings, and q is unbounded.
 *
 * @param {URLSearchParams} params
 * @returns {TopicId | null}
 */
export function soleTopic(params) {
  const topics = params.getAll("topic").filter((t) => TOPIC_IDS.has(t));
  const KNOWN_PARAMS = new Set(["topic", "q", "sort", "selected"]);
  const hasUnknownParam = [...params.keys()].some((k) => !KNOWN_PARAMS.has(k));
  return topics.length === 1 &&
    params.getAll("topic").length === 1 &&
    !params.has("q") &&
    !params.has("sort") &&
    !params.has("selected") &&
    !hasUnknownParam
    ? /** @type {TopicId} */ (topics[0])
    : null;
}

/**
 * The page's state for an address: the showcase papers run through the catalog, with the span the header states and the
 * canonical topic. Everything shown is in `result`.
 *
 * @param {URLSearchParams} params
 * @param {Publication[]} publications every published paper, newest first (app/db/publications.ts)
 */
export function publicationListing(params, publications) {
  const showcase = publications.filter((p) => SHOWCASE_TYPES.has(p.type));
  const result = queryCatalog(PUBLICATIONS, showcase, parseCatalogParams(PUBLICATIONS, params));
  const items = result.rows;
  const span = {
    papers: items.length,
    firstYear: items.length > 0 ? Math.min(...items.map((p) => p.year)) : null,
    lastYear: items.length > 0 ? Math.max(...items.map((p) => p.year)) : null,
    venues: new Set(items.map((p) => p.journal).filter(Boolean)).size,
  };
  return { items, result, span, soleTopic: soleTopic(params), total: showcase.length };
}

app/lib/return-to.mjs.source:
/**
 * The `Referer` is attacker-supplied, so it is proven same-origin before the toggle redirects to it.
 *
 * @param {Request} request
 * @returns {string}
 */
export function safeReturnTo(request) {
  const referer = request.headers.get("referer");
  if (!referer) return "/";
  try {
    const url = new URL(referer);
    if (url.origin !== new URL(request.url).origin) return "/";
    // `new URL("https://site//evil.com")` has pathname `//evil.com`, and `Location: //evil.com`
    // is protocol-relative, resolving against another HOST. The origin check does not catch it.
    if (url.pathname.startsWith("//")) return "/";
    // `Referer` never carries a fragment (RFC 9110), so `url.hash` is empty for browser requests;
    // it is echoed for callers that pass a URL from elsewhere.
    return url.pathname + url.search + url.hash;
  } catch {
    return "/";
  }
}

app/lib/search/follow-up.mjs.source:
// Not in ask-prompt.mjs: the client imports this, and importing from there shipped the system prompt
// in the client bundle (tree-shaking did not remove it), which would make answerLeaksPrompt moot.

/** A marker, not "the last line": splitting on position would eat a sentence when no follow-up came. */
export const FOLLOW_UP_MARKER = "NEXT:";

/**
 * The marker must start a line (mid-sentence it is prose), and is searched from the end, since the
 * follow-up is asked for last.
 *
 * @param {string} raw
 * @returns {{ answer: string, followUp: string | null }}
 */
export function splitFollowUp(raw) {
  const lines = raw.split("\n");
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    /* The ?? "" only satisfies noUncheckedIndexedAccess. */
    const line = (lines[i] ?? "").trim();
    if (!line.startsWith(FOLLOW_UP_MARKER)) continue;
    const question = line.slice(FOLLOW_UP_MARKER.length).trim();
    const answer = lines.slice(0, i).join("\n").trimEnd();
    return { answer, followUp: question.length > 0 ? question : null };
  }
  return { answer: raw, followUp: null };
}

app/lib/series-path.mjs.source:
/**
 * A series is FREE TEXT, unlike a tag, so it is normalized here and nowhere else; the archive
 * builds and resolves its URL through this one function so the two cannot drift.
 */

/**
 * Empty for a name with no alphanumerics; the caller decides what that means.
 *
 * @param {string} name
 * @returns {string}
 */
export function seriesSlug(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Takes the NAME, so no caller can forget to slugify and put two spellings of one URL on the site.
 *
 * @param {string} name
 * @returns {string} a site-absolute path
 */
export function seriesPath(name) {
  return `/writing/series/${encodeURIComponent(seriesSlug(name))}`;
}

app/lib/transition-abort.mjs.source:
// A cross-document view transition (motion-print.css, type `site`) the browser abandons rejects its promises with
// `InvalidStateError: Transition was aborted because of invalid state`: the page was reloaded, went hidden or was
// navigated again while the transition was still running. Nothing in the page caused it and nothing in the page can
// handle it, since the promise belongs to the browser's own navigation. It is the one error the page lets go: every
// other rejection, including any other InvalidStateError, is still reported.

/**
 * Whether a rejection is the browser abandoning a view transition.
 *
 * @param {unknown} reason
 */
export function isAbandonedTransition(reason) {
  return reason instanceof DOMException && reason.name === "InvalidStateError" && reason.message.startsWith("Transition was aborted");
}

app/kb/libraries.mjs.source:
// The libraries of the knowledge bases other than Protocols (docs/KNOWLEDGE-BASE.md, step 8): Recipes and Software
// how-tos, each a catalog over its base's published procedure records, declared once here for Capsomer's catalog as the
// protocol library is in procedures/library.mjs. The page, its facets, its downloads and its markdown twin all read the
// declaration, and every fact is drawn from the records, never typed. Pure: the routes pass in the records from D1.

import { catalogRedirect, defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { BASES } from "./bases.mjs";
import { stepCount } from "./procedures/library.mjs";
import { courseLabel, methodLabel } from "./procedures/taxonomy.mjs";
import { HOWTO_TYPES } from "./procedures/validate.mjs";

/** A how-to's type in words: "how-to" is "How-to". @param {string} id */
export const howtoTypeLabel = (id) => HOWTO_TYPES[/** @type {keyof typeof HOWTO_TYPES} */ (id)] ?? id;

/** @typedef {import("./bases.mjs").KnowledgeBase} KnowledgeBase */
/** @typedef {import("./procedures/render.mjs").ProcedureRecord} ProcedureRecord */

/** The bases that have a library here: every base but Protocols, whose library is its own (procedures/library.mjs). */
export const LIBRARY_BASES = Object.freeze(BASES.filter((base) => base.profile !== "protocol"));

/** The base whose library is at `path`, or null. @param {string} path */
export function baseAtLibrary(path) {
  return LIBRARY_BASES.find((base) => base.library === path.replace(/\/+$/, "")) ?? null;
}

/**
 * The trail to a library: a how-to's under Software, a recipe's on its own. The entry pages' trails extend it.
 *
 * @param {KnowledgeBase} base
 * @returns {Array<[string, string]>}
 */
export function libraryTrail(base) {
  return base.profile === "computational" ? [["Software", "/software"], [base.name, base.library]] : [[base.name, base.library]];
}

/** A record's times in words: "Prep 15 min, cook 40 min", else its total. @param {ProcedureRecord} r */
function timeOf(r) {
  const parts = [r.prepTime ? `prep ${r.prepTime}` : "", r.cookTime ? `cook ${r.cookTime}` : ""].filter(Boolean).join(", ");
  if (parts) return parts.charAt(0).toUpperCase() + parts.slice(1);
  return r.time?.total ? String(r.time.total) : "";
}

/**
 * The library's rows: the base's published records, each reduced to what its catalog reads.
 *
 * @param {KnowledgeBase} base
 * @param {ProcedureRecord[]} records
 */
export function baseItems(base, records) {
  return records
    .filter((r) => r.profile === base.profile)
    .map((r) => ({
      slug: r.slug,
      path: r.path,
      title: r.title,
      description: r.description,
      updated: r.updated ? String(r.updated) : "",
      steps: stepCount(r),
      time: timeOf(r),
      // Recipe.
      servings: r.servings ?? null,
      cuisine: r.cuisine ? String(r.cuisine) : "",
      category: r.category ? String(r.category) : "",
      diet: r.diet ?? [],
      // Software how-to: tutorial or how-to (S1), empty for a row compiled before it had one.
      type: r.howtoType ?? "",
      methods: r.methods ?? [],
      courses: r.courses ?? [],
    }));
}

/** @typedef {ReturnType<typeof baseItems>[number]} BaseItem */

/** The noun a base's entries are counted with: ["recipe", "recipes"]. @param {KnowledgeBase} base @returns {[string, string]} */
export const nounOf = (base) => [base.singular.toLowerCase(), base.name.toLowerCase()];

// Isolate-wide: a base's catalog is built from its definition, the same for every request.
/** @type {Map<string, import("capsomer/behavior/catalog").CatalogDefinition<BaseItem>>} */
const catalogs = new Map();

/**
 * A base's catalog: the fields its facets, columns and sort menu list, in that order. A recipe is found by its category,
 * cuisine and diet; a how-to by the method and course it serves.
 *
 * @param {KnowledgeBase} base
 */
export function baseCatalog(base) {
  const known = catalogs.get(base.id);
  if (known) return known;
  const title = { key: "title", label: base.singular, value: (/** @type {BaseItem} */ p) => p.title, search: 3, column: { header: base.singular }, sort: true };
  const description = { key: "description", label: "Description", value: (/** @type {BaseItem} */ p) => p.description, search: 1 };
  const updated = { key: "updated", label: "Updated", value: (/** @type {BaseItem} */ p) => p.updated, type: "date", sort: { labels: { asc: "Updated, oldest first", desc: "Updated, newest first" } } };
  const fields =
    base.profile === "recipe"
      ? [
          title,
          description,
          { key: "category", label: "Category", value: (/** @type {BaseItem} */ p) => (p.category ? [p.category] : []), facet: { kind: "many", order: "alpha" }, column: { header: "Category", drop: 1 }, search: 1 },
          { key: "cuisine", label: "Cuisine", value: (/** @type {BaseItem} */ p) => (p.cuisine ? [p.cuisine] : []), facet: { kind: "many", order: "alpha" }, search: 1 },
          { key: "diet", label: "Diet", value: (/** @type {BaseItem} */ p) => p.diet, facet: { kind: "many", order: "alpha" } },
          { key: "servings", label: "Servings", value: (/** @type {BaseItem} */ p) => p.servings ?? 0, type: "number", column: { header: "Servings", align: "end", drop: 2 } },
          { key: "time", label: "Time", value: (/** @type {BaseItem} */ p) => p.time, column: { header: "Time", drop: 2 } },
          updated,
        ]
      : [
          title,
          description,
          { key: "type", label: "Type", value: (/** @type {BaseItem} */ p) => (p.type ? [p.type] : []), facet: { kind: "many", label: howtoTypeLabel }, column: { header: "Type", drop: 1 } },
          { key: "method", label: "Method", value: (/** @type {BaseItem} */ p) => p.methods, facet: { kind: "many", label: methodLabel }, column: { header: "Method", drop: 1 }, search: 1 },
          { key: "course", label: "Course", value: (/** @type {BaseItem} */ p) => p.courses, facet: { kind: "many", label: courseLabel } },
          { key: "steps", label: "Steps", value: (/** @type {BaseItem} */ p) => p.steps, type: "number", sort: true, column: { header: "Steps", align: "end", drop: 2 } },
          updated,
        ];
  const catalog = defineCatalog(
    /** @type {import("capsomer/behavior/catalog").CatalogDefinition<BaseItem>} */ ({
      id: base.id,
      noun: nounOf(base),
      basePath: base.library,
      itemKey: (p) => p.slug,
      defaultSort: "title",
      pageSize: 25,
      fields,
    }),
  );
  catalogs.set(base.id, catalog);
  return catalog;
}

/**
 * The address a request should have, or null: the catalog's own clean address, with unknown parameters (a tracking
 * tag) served rather than redirected, as the protocol library does.
 *
 * @param {KnowledgeBase} base
 * @param {URL} url
 */
export function baseRedirect(base, url) {
  const catalog = baseCatalog(base);
  const known = new Set(["q", "sort", "page", ...catalog.fields.filter((f) => f.facet).map((f) => f.key)]);
  const kept = new URLSearchParams();
  for (const [key, value] of url.searchParams) if (known.has(key)) kept.append(key, value);
  const only = new URL(url);
  only.search = kept.toString();
  return catalogRedirect(catalog, only);
}

/**
 * The library as rows for a download, for the filter state in the address: every fact the page shows, ids with their
 * words. The CSV and the JSON are both this.
 *
 * @param {KnowledgeBase} base
 * @param {BaseItem[]} items
 * @param {URLSearchParams | string} params
 * @param {string} origin
 */
export function baseRecords(base, items, params, origin) {
  const catalog = baseCatalog(base);
  const state = parseCatalogParams(catalog, params);
  return queryCatalog({ ...catalog, pageSize: undefined }, items, { ...state, page: 1 }).rows.map((p) => ({
    id: p.slug,
    title: p.title,
    url: `${origin}${p.path}`,
    ...(base.profile === "recipe"
      ? { category: p.category, cuisine: p.cuisine, diet: p.diet, servings: p.servings, time: p.time }
      : { type: p.type ? howtoTypeLabel(p.type) : "", methods: p.methods.map(methodLabel), courses: p.courses.map(courseLabel), steps: p.steps }),
    updated: p.updated,
    description: p.description,
  }));
}

/** One cell of a markdown table. @param {string} text */
const cell = (text) => text.replaceAll("|", "\\|").replace(/\s+/g, " ").trim();

/**
 * The twin's table: every entry with the facts the page shows, linked to its own page. An empty library says so.
 *
 * @param {KnowledgeBase} base
 * @param {BaseItem[]} items
 * @param {string} origin
 */
export function baseMarkdown(base, items, origin) {
  if (items.length === 0) return `No ${base.name.toLowerCase()} are published yet.`;
  const recipe = base.profile === "recipe";
  const head = recipe ? [base.singular, "Category", "Cuisine", "Diet", "Servings", "Time", "Updated"] : [base.singular, "Type", "Method", "Course", "Steps", "Updated"];
  const rows = items.map((p) =>
    (recipe
      ? [`[${cell(p.title)}](${origin}${p.path})`, p.category, p.cuisine, p.diet.join(", "), p.servings === null ? "" : String(p.servings), p.time, p.updated]
      : [`[${cell(p.title)}](${origin}${p.path})`, p.type ? howtoTypeLabel(p.type) : "", p.methods.map(methodLabel).join(", "), p.courses.map(courseLabel).join(", "), String(p.steps), p.updated]
    ).map((c, i) => (i === 0 ? c : cell(c))),
  );
  return [`| ${head.join(" | ")} |`, `| ${head.map(() => "---").join(" | ")} |`, ...rows.map((r) => `| ${r.join(" | ")} |`)].join("\n");
}

/** The downloads of a view, carrying its filter state; the twin is always the whole library. @param {KnowledgeBase} base @param {{ href: () => string }} result */
export function baseDownloads(base, result) {
  const href = result.href();
  const query = href.includes("?") ? href.slice(href.indexOf("?")) : "";
  return { csv: `${base.library}.csv${query}`, json: `${base.library}.json${query}`, markdown: `${base.library}.md` };
}

/** How to cite the library, from the site's identity and the library's address. @param {KnowledgeBase} base @param {{ name: string, affiliation: string, origin: string }} who */
export function baseCitation(base, { name, affiliation, origin }) {
  return {
    library: `${name}. ${base.name}. ${name} Lab, ${affiliation}. ${origin}${base.library}`,
    access: "Add the date you accessed it.",
    protocol: `To cite one ${base.singular.toLowerCase()}, cite its own page: its title, the lab, the institution, its address and the date you accessed it.`,
  };
}

app/kb/procedures/lineage.mjs.source:
// A variant's lineage (docs/KNOWLEDGE-BASE.md, P3): the procedure it was copied from with the editor's Duplicate, as the
// page, the twin and the JSON-LD name it. The file holds only `forked_from: { slug, version }`; the parent's title and
// address are its own facts, read from its row when the page is served, so a renamed parent reads right everywhere.

import { BASES } from "../bases.mjs";
import { versionPath } from "./cite.mjs";

/**
 * @typedef {{ title: string, href: string | null, version: string | null }} Lineage
 */

/**
 * Where a variant points: the frozen copy of the version it was copied at when there is one, else the parent's live page,
 * else (a parent not published) its name with no link.
 *
 * @param {{ slug: string, version: string | null } | null} forkedFrom
 * @param {string} profile
 * @param {{ live: { title: string, path: string } | null, frozen: { title: string } | null }} parent
 * @returns {Lineage | null}
 */
export function resolveLineage(forkedFrom, profile, parent) {
  if (!forkedFrom) return null;
  const root = BASES.find((b) => b.profile === profile)?.entryRoot ?? "/research/protocols/";
  const path = `${root}${forkedFrom.slug}`;
  if (forkedFrom.version && parent.frozen) return { title: parent.frozen.title, href: versionPath(path, forkedFrom.version), version: forkedFrom.version };
  if (parent.live) return { title: parent.live.title, href: parent.live.path, version: forkedFrom.version };
  return { title: forkedFrom.slug, href: null, version: forkedFrom.version };
}

/** "Phage DNA extraction, version 2": the words the lineage is shown in. @param {Lineage} lineage */
export const lineageText = (lineage) => `${lineage.title}${lineage.version ? `, version ${lineage.version}` : ""}`;

/** The twin's fact line for a lineage, as the page's fact reads. @param {Lineage} lineage @param {string} origin */
const lineageMarkdown = (lineage, origin) => `- Based on: ${lineage.href ? `[${lineageText(lineage)}](${origin}${lineage.href})` : lineageText(lineage)}`;

/**
 * The fact the stored twin carries for a variant: the parent's file name and version, all the compile knows. The twin's
 * routes swap it for the parent's title and address when they serve it (`withLineage`).
 *
 * @param {{ slug: string, version: string | null }} forkedFrom
 */
export const storedLineage = (forkedFrom) => `${forkedFrom.slug}${forkedFrom.version ? `, version ${forkedFrom.version}` : ""}`;

/**
 * A twin with its stored lineage fact read out in full: the parent's title, linked to the copy it was taken from.
 *
 * @param {string} markdown
 * @param {{ forkedFrom: { slug: string, version: string | null } | null }} record
 * @param {Lineage | null} lineage
 * @param {string} origin
 */
export function withLineage(markdown, record, lineage, origin) {
  if (!record.forkedFrom || !lineage) return markdown;
  return markdown.replace(`- Based on: ${storedLineage(record.forkedFrom)}\n`, `${lineageMarkdown(lineage, origin)}\n`);
}

/**
 * What is wrong with a variant's `forked_from` against the procedures in the repository (P3): the parent is a file
 * here, of the same profile, and the version named is one the parent states (its current version or one in its history),
 * which is a version that is or will be frozen. The shape is validate.mjs's; this is the corpus check:protocols runs.
 *
 * @param {{ forkedFrom: { slug: string, version: string | null } | null, profile: string }} record
 * @param {Map<string, { profile: string, version: string | null, history: Array<{ version: string }> }>} procedures by slug
 * @returns {string[]}
 */
export function lineageErrors(record, procedures) {
  const from = record.forkedFrom;
  if (!from) return [];
  const parent = procedures.get(from.slug);
  if (!parent) return [`forked_from names ${from.slug}, which is not a procedure here`];
  if (parent.profile !== record.profile) return [`forked_from names ${from.slug}, a ${parent.profile}; a variant keeps its parent's profile (${record.profile})`];
  if (!from.version) return [];
  const stated = new Set([parent.version, ...parent.history.map((h) => h.version)].filter(Boolean));
  return stated.has(from.version) ? [] : [`forked_from names version ${from.version} of ${from.slug}, which states ${[...stated].join(", ") || "no version"}`];
}

app/kb/procedures/render.mjs.source:
// Turns a parsed, validated procedure into the record D1 stores and the page draws: every markdown
// fragment rendered to HTML through the site's own pipeline (so links pass the same URL allowlist as a
// post), every gap left out, and the quantities a reader can scale left as numbered slots in the HTML.
// The markdown twin and the search inputs are derived here too, from the same parse, so a machine and a
// person read the same facts.
//
// `renderBody` is passed in, not imported: the pipeline is 4 MB, so the Worker loads it lazily
// (load-pipeline.server.ts) and a Node script imports it directly.

import GithubSlugger from "github-slugger";

import { TOOLS } from "../../lib/phage-tools.mjs";
import { productsForRows } from "../registry/align.mjs";
import { itemPath } from "../registry/catalog.mjs";
import { plainText } from "../../lib/search/records.mjs";
import { keyResources, keyResourcesMarkdown } from "./key-resources.mjs";
import { proofFromFile } from "./proof.mjs";
import { formatQuantity, readConditions, segmentText } from "./marks.mjs";
import { statusLabel } from "./taxonomy.mjs";
import { allSteps, PLATFORMS, procedurePath, readCalcs } from "./parse.mjs";
import { HOWTO_TYPES } from "./validate.mjs";
import { storedLineage } from "./lineage.mjs";

/** The slot a scalable quantity leaves in a step's HTML, filled at request time (fillQuantities). */
const SLOT = (/** @type {number} */ i) => `QZQ${i}QZQ`;
const SLOT_PATTERN = /QZQ(\d+)QZQ/g;

const GAP = /^MISSING:/;

/** A heading as the pipeline writes it: rehype-slug's id, then the autolink inside. */
const HEADING = /<h([1-6]) id="([^"]+)">([\s\S]*?)<\/h\1>/g;

/**
 * The ids of the sections the components draw from the front matter (ProcedureView), so a prose
 * heading with the same words takes the -1 suffix rather than the fixed section's id.
 *
 * @param {unknown} profile
 */
export function fixedSectionIds(profile) {
  const materials = profile === "recipe" ? "ingredients" : profile === "computational" ? "software-and-data" : "reagents";
  const fixed = [materials, "equipment", "primers", "troubleshooting", "expected-results", "limitations", "references", "proof-of-use", "version-history", "cite-this-procedure", "key-resources"];
  // A how-to's own sections (S2, S1), after the shared ones so no protocol's prose heading changes its id.
  return profile === "computational" ? [...fixed, "overview", "questions", "objectives", "key-points", "explanation"] : fixed;
}

/**
 * The value, or null when it is a recorded gap or absent.
 *
 * @template T
 * @param {T} value
 * @returns {T | null}
 */
function known(value) {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value === "string" && GAP.test(value)) return null;
  return value;
}

/** @param {unknown} v */
const list = (v) => (Array.isArray(v) ? v : v === undefined || v === null ? [] : [v]);

/**
 * @typedef {(input: { file: string, body: string, resolveImage: (src: string) => Promise<any> }) =>
 *   Promise<{ html: string, toc: Array<{ depth: number, id: string, text: string }>, blockedUrls: Array<{ url: string }> }>} RenderBody
 */

/**
 * A primer as a protocol carries it: the lab registry's own facts about it, read when the protocol is compiled and stored
 * in the record, so the page, the sheet, the twin and a frozen version all print the same sequence, and the protocol's
 * file holds none (docs/REGISTRY.md). Its Tm and length are computed from the sequence where they are shown.
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", set: string | null, direction: string | null, sequence: string | null, reference: string | null, publishedIn?: string | null }} StoredPrimer
 */

/**
 * A host strain as a protocol carries it: the lab registry's stated facts about it, read when the protocol is compiled and
 * stored in the record, so the page, the twin and a frozen version name one strain and the protocol's file types none.
 *
 * A reagent as a protocol carries it: the lab registry's name for it, read when the protocol is compiled, so a material that
 * names a reagent shows the registry's name and links its page and a frozen version keeps the name it was published with.
 *
 * An equipment item as a protocol carries it: the registry's stated facts (who makes it, and a centrifuge's rotor, or that the rotor
 * is a recorded gap), read when the protocol is compiled, so the protocol's Equipment table and twin say as it was published.
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", manufacturer: string | null, rotor: string | null, rotorGap: boolean }} StoredEquipment
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", preparedInLab: boolean, supplier: string | null, catalogNumber: string | null, productUrl: string | null, recipe: string | null }} StoredReagent
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", organism: string | null, strain: string | null, collection: string | null, collectionNumber: string | null }} StoredStrain
 */

/**
 * Where a reagent comes from, in the words a protocol's table and twin use: a bought reagent's supplier and catalog number, linked to
 * its product page where there is one; a reagent prepared in the lab, linked to its recipe where one exists.
 *
 * @param {StoredReagent} reagent
 * @returns {{ text: string, href: string | null }}
 */
export function reagentSource(reagent) {
  if (reagent.preparedInLab) {
    return { text: reagent.recipe ? "Prepared in the lab (recipe)" : "Prepared in the lab", href: reagent.recipe ? `/recipes/${reagent.recipe}` : null };
  }
  const text = [reagent.supplier, reagent.catalogNumber].filter(Boolean).join(", ");
  return { text: text || "Not recorded", href: reagent.productUrl };
}

/**
 * @param {{
 *   slug: string,
 *   parsed: import("./parse.mjs").ParsedProcedure,
 *   gaps: Array<{ field: string, reason: string }>,
 *   renderBody: RenderBody,
 *   resolveImage?: (src: string) => Promise<{ width: number, height: number }>,
 *   primerRows?: StoredPrimer[],
 *   strainRows?: Array<StoredStrain & { path: string }>,
 *   organismNames?: Record<string, string>,
 *   reagentRows?: StoredReagent[],
 *   equipmentRows?: StoredEquipment[],
 * }} input
 */
export async function renderProcedure({ slug, parsed, gaps, renderBody, resolveImage, primerRows, strainRows, organismNames, reagentRows, equipmentRows }) {
  const file = procedurePath(slug);
  const d = parsed.data;
  const refuseImage = async (/** @type {string} */ src) => {
    throw new Error(`${file}: an image in prose ("${src}") is not supported; recipes carry photos on a step's own line`);
  };

  /**
   * @param {unknown} markdown
   * @param {{ inline?: boolean }} [opts]
   */
  const md = async (markdown, opts = {}) => {
    if (typeof markdown !== "string" || !markdown.trim() || GAP.test(markdown)) return null;
    const out = await renderBody({ file, body: markdown, resolveImage: refuseImage });
    if (out.blockedUrls.length > 0) {
      throw new Error(`${file}: the URL allowlist refused ${out.blockedUrls.map((b) => b.url).join(", ")}`);
    }
    const html = out.html.trim();
    if (!opts.inline) return html;
    const single = /^<p>([\s\S]*)<\/p>$/.exec(html);
    return single && !single[1]?.includes("<p>") ? (single[1] ?? "") : html;
  };

  /** @param {{ src: string, alt: string }} photo */
  const photo = async (photo) => {
    if (!resolveImage) return { src: photo.src, alt: photo.alt, width: null, height: null };
    const size = await resolveImage(photo.src);
    return { src: photo.src, alt: photo.alt, width: size.width, height: size.height };
  };

  /** @param {unknown} value */
  const inlineList = async (value) =>
    /** @type {string[]} */ ((await Promise.all(list(known(value)).map((/** @type {string} */ x) => md(x, { inline: true })))).filter(Boolean));

  const materialsByName = new Map(list(d.materials).map((/** @type {any} */ m) => [String(m.name).toLowerCase(), m]));

  /** @param {import("./parse.mjs").Step} step */
  const renderStep = async (step) => {
    /** @type {Array<{ name: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }>} */
    const quantities = [];
    /** @type {Array<{ name: string, display: string, amount: string | null }>} */
    const materials = [];
    /** @type {string[]} */
    const equipment = [];
    /** @type {Array<{ label: string, text: string, min: number | null, max: number | null, unit: string }>} */
    const timers = [];
    let words = "";
    for (const seg of step.segments) {
      if (seg.type === "material") {
        materials.push({
          name: seg.name,
          display: seg.display,
          amount: seg.quantity ? formatQuantity(seg.quantity) : null,
        });
        if (seg.quantity) {
          quantities.push({
            // Which ingredient the amount is of, so a recipe can show it in other units (recipe-views.mjs).
            name: seg.name,
            amount: seg.quantity.amount,
            unit: seg.quantity.unit,
            fixed: seg.quantity.fixed,
            min: seg.quantity.min,
            max: seg.quantity.max,
          });
          words += `${SLOT(quantities.length - 1)} of ${seg.display}`;
          continue;
        }
      } else if (seg.type === "equipment") {
        equipment.push(seg.name);
      } else if (seg.type === "timer" && seg.quantity) {
        timers.push({
          label: seg.label,
          text: formatQuantity(seg.quantity),
          min: seg.quantity.min,
          max: seg.quantity.max,
          unit: seg.quantity.unit,
        });
      }
      words += segmentText(seg);
    }
    const text = step.segments.map((s) => segmentText(s)).join("");
    const { temperatures, spins } = readConditions(text);
    const flagHtml = async (/** @type {string[]} */ items) =>
      /** @type {string[]} */ ((await Promise.all(items.map((t) => md(t)))).filter(Boolean));
    return {
      number: step.number,
      html: await md(words, { inline: true }),
      text: plainText(text),
      quantities,
      materials,
      equipment,
      timers,
      temperatures,
      spins,
      spin: step.flags.spin.filter((s) => !GAP.test(s)),
      critical: await flagHtml(step.flags.critical),
      pause: await flagHtml(step.flags.pause),
      why: await flagHtml(step.flags.why),
      expect: await flagHtml(step.flags.expect),
      troubleshooting: step.flags.troubleshooting,
      calculators: readCalcs(step.flags.calc),
      // A tutorial's challenges, each with the solution the parse paired with it (S5).
      challenges: await Promise.all(
        step.flags.challenge.map(async (c, i) => ({ html: await md(c), solutionHtml: await md(step.flags.solution[i] ?? "") })),
      ),
      commands: step.commands,
      photos: await Promise.all(step.photos.map(photo)),
    };
  };

  // One slugger for the whole page, as rehype-slug has for a whole post: each prose block is rendered
  // on its own, so a heading repeated across blocks would otherwise keep one id twice. The sections the
  // components draw themselves take their ids first.
  const slugger = new GithubSlugger();
  for (const id of fixedSectionIds(d.profile)) slugger.slug(id);
  /** @type {Array<{ depth: number, id: string, text: string }>} */
  const toc = [];
  /** @type {Array<{ id: string, title: string, blocks: Array<{ type: "prose", html: string } | { type: "steps", steps: Array<Awaited<ReturnType<typeof renderStep>>> }> }>} */
  const sections = [];
  for (const section of parsed.sections) {
    const sectionId = section.custom ? section.id : slugger.slug(section.title);
    toc.push({ depth: 2, id: sectionId, text: section.title });
    /** @type {(typeof sections)[number]["blocks"]} */
    const blocks = [];
    for (const block of section.blocks) {
      if (block.type === "prose") {
        const out = await renderBody({ file, body: block.markdown, resolveImage: refuseImage });
        if (out.blockedUrls.length > 0) {
          throw new Error(`${file}: the URL allowlist refused ${out.blockedUrls.map((b) => b.url).join(", ")}`);
        }
        const html = out.html.replace(HEADING, (_all, level, id, inner) => {
          const text = String(inner).replace(/<[^>]+>/g, "").replace(/#$/, "").trim();
          const unique = slugger.slug(text);
          if (Number(level) === 3) toc.push({ depth: 3, id: unique, text });
          return `<h${level} id="${unique}">${String(inner).replace(`href="#${id}"`, `href="#${unique}"`)}</h${level}>`;
        });
        blocks.push({ type: "prose", html });
      } else {
        blocks.push({ type: "steps", steps: await Promise.all(block.steps.map(renderStep)) });
      }
    }
    sections.push({ id: sectionId, title: section.title, blocks });
  }

  const reagentsById = new Map((reagentRows ?? []).map((r) => [r.id, r]));
  const materials = await Promise.all(
    list(d.materials).map(async (/** @type {any} */ m) => ({
      name: m.name,
      // A reagent of the registry is shown by the registry's name, linked, so the protocol types no product name for it.
      display: m.display ?? reagentsById.get(m.reagent)?.name ?? m.name,
      // What the registry says of it, as it was when the protocol was compiled: the table shows where it comes from.
      reagent: reagentsById.get(m.reagent) ?? null,
      group: m.group ?? null,
      kind: m.kind ?? null,
      version: known(m.version),
      stock: list(m.stock).filter((s) => known(s) !== null).map(String),
      final: known(m.final),
      amount: known(m.amount),
      per: known(m.per),
      solution: m.solution ?? null,
      noteHtml: await md(m.note, { inline: true }),
      // A recipe's grams in one cup of it, where the recipe states it: the only way its volume is shown as weight (DECIDE 7).
      gramsPerCup: typeof m.grams_per_cup === "number" && m.grams_per_cup > 0 ? m.grams_per_cup : null,
      /** @type {{ amount: string, unit: string, fixed: boolean, min: number | null, max: number | null } | null} */
      quantity: null,
    })),
  );

  // A material with no amount of its own takes the sum of what its marks use, when they share a unit and
  // none is fixed, so a recipe's shopping list scales with its servings.
  /** @param {string} name */
  const markedTotal = (name) => {
    const qs = allSteps(parsed).flatMap((s) =>
      s.segments.flatMap((seg) => (seg.type === "material" && seg.name.toLowerCase() === name.toLowerCase() && seg.quantity ? [seg.quantity] : [])),
    );
    const unit = qs[0]?.unit;
    if (qs.length === 0 || qs.some((q) => q.min === null || q.max !== q.min || q.unit !== unit)) return null;
    const sum = qs.reduce((n, q) => n + (q.min ?? 0), 0);
    return { amount: String(sum), unit: unit ?? "", fixed: qs.every((q) => q.fixed), min: sum, max: sum };
  };
  for (const m of materials) {
    if (m.amount === null) m.quantity = markedTotal(m.name);
  }

  // A recipe may leave its ingredients undeclared: the marks are the list, in order of first use.
  if (d.profile === "recipe") {
    for (const step of allSteps(parsed)) {
      for (const seg of step.segments) {
        if (seg.type !== "material" || materialsByName.has(seg.name.toLowerCase())) continue;
        materialsByName.set(seg.name.toLowerCase(), { name: seg.name });
        materials.push({
          name: seg.name,
          display: seg.name,
          reagent: null,
          group: null,
          kind: null,
          version: null,
          stock: [],
          final: null,
          amount: null,
          per: null,
          solution: null,
          noteHtml: null,
          gramsPerCup: null,
          quantity: markedTotal(seg.name),
        });
      }
    }
  }

  const troubleshooting = await Promise.all(
    list(d.troubleshooting).map(async (/** @type {any} */ row) => ({
      id: row.id,
      step: String(row.step),
      problem: await md(row.problem, { inline: true }),
      reason: await md(row.reason, { inline: true }),
      solution: await md(row.solution, { inline: true }),
    })),
  );

  const image = known(d.image);
  const record = {
    slug,
    profile: /** @type {"protocol" | "recipe" | "computational"} */ (d.profile),
    path: String(d.path),
    title: String(d.title),
    seoTitle: String(d.seo_title),
    description: String(d.description),
    draft: d.draft === true,
    version: known(d.version) === null ? null : String(d.version),
    // Newest first; the first entry is the version the page is at (validate.mjs). Empty until one is written.
    history: await Promise.all(
      list(known(d.history)).map(async (/** @type {any} */ h) => ({
        version: String(h.version),
        date: String(h.date),
        summaryHtml: await md(h.summary, { inline: true }),
        doi: h.doi ? String(h.doi) : null,
      })),
    ),
    updated: known(d.updated),
    // What the protocol library filters and lists by (taxonomy.mjs); ids, so the page draws the words.
    methods: /** @type {string[]} */ (list(known(d.method))),
    organisms: /** @type {string[]} */ (list(known(d.organism))),
    // The words for each organism id, read from the lab registry when the protocol was compiled (docs/REGISTRY.md).
    organismNames: organismNames ?? {},
    targets: /** @type {string[]} */ (list(known(d.target))),
    courses: /** @type {string[]} */ (list(known(d.course))),
    // The library's "Start here" position, or null: stored, never inferred.
    startHere: known(d.start_here) === null ? null : Number(d.start_here),
    // Proof of use: slugs of the papers that used the method and the phages it produced, or null. Stored, never inferred.
    proofOfUse: proofFromFile(known(d.proof_of_use)),
    firstUsed: known(d.first_used),
    lastRun: known(d.last_run),
    status: known(d.status) === null ? null : statusLabel(String(d.status)),
    // The procedure this one was copied from with the editor's Duplicate (validate.mjs checks the shape), or null.
    forkedFrom:
      d.forked_from && typeof d.forked_from === "object"
        ? { slug: String(d.forked_from.slug), version: d.forked_from.version ? String(d.forked_from.version) : null }
        : null,
    time: {
      total: known(d.time?.total),
      handsOn: known(d.time?.hands_on),
    },
    introHtml: await md(parsed.intro),
    basedOn: list(known(d.based_on)).map((/** @type {any} */ s) => ({
      citation: String(s.citation),
      for: String(s.for),
      doi: s.doi ? String(s.doi) : null,
      url: s.url ? String(s.url) : null,
    })),
    references: /** @type {string[]} */ (
      (await Promise.all(list(known(d.references)).map((/** @type {string} */ r) => md(r, { inline: true })))).filter(Boolean)
    ),
    materials,
    equipment: await Promise.all(
      list(d.equipment).map(async (/** @type {any} */ e) => {
        const item = typeof e === "object" && e !== null ? ((equipmentRows ?? []).find((r) => r.id === e.equipment) ?? null) : null;
        return typeof e === "string" ? { name: e, noteHtml: null, item } : { name: String(e.name), noteHtml: await md(e.note, { inline: true }), item };
      }),
    ),
    troubleshooting,
    expectedResultsHtml: await md(d.expected_results),
    limitationsHtml: await md(d.limitations),
    sections,
    toc,
    // Protocol.
    scale: known(d.scale) ? { count: Number(d.scale.count), unit: String(d.scale.unit) } : null,
    biosafety: known(d.biosafety) && d.biosafety !== "not applicable" ? d.biosafety : null,
    // Dustin's to set per protocol. A gap reads as null, so no page, twin or structured data ever carries "MISSING".
    biosafetyLevel: /** @type {string | null} */ (known(d.biosafety_level)),
    // The strains are the registry's: the names are computed from them, never typed in the protocol.
    hostStrains: (strainRows ?? []).map((s) => ({ id: s.id, name: s.name, path: s.path, organism: s.organism, strain: s.strain, collection: s.collection, collectionNumber: s.collectionNumber })),
    hostStrain: (strainRows ?? []).length > 0 ? (strainRows ?? []).map((s) => s.name).join("; ") : null,
    solutions: list(d.solutions).map((/** @type {any} */ s) => ({
      id: s.id,
      name: s.name,
      components: list(s.components).map((/** @type {any} */ c) => ({
        name: String(c.name),
        final: known(c.final),
        amount: known(c.amount),
      })),
      storage: known(s.storage),
      shelfLife: known(s.shelf_life),
    })),
    // The registry's rows for the primers the file names, in the file's order (compile.mjs resolves them).
    primers: (primerRows ?? []).map((p) => ({ id: p.id, name: p.name, set: p.set, direction: p.direction, sequence: p.sequence, reference: p.reference, publishedIn: p.publishedIn ?? null })),
    cycling: Array.isArray(d.cycling) ? d.cycling : [],
    // Recipe.
    servings: known(d.servings) === null ? null : Number(d.servings),
    cuisine: known(d.cuisine),
    category: known(d.category),
    diet: list(known(d.diet)).map(String),
    prepTime: known(d.prep_time),
    cookTime: known(d.cook_time),
    image: image ? await photo(image) : null,
    substitutions: await Promise.all(
      list(d.substitutions).map(async (/** @type {any} */ s) => ({
        for: String(s.for),
        use: String(s.use),
        noteHtml: await md(s.note, { inline: true }),
      })),
    ),
    // Computational.
    // Tutorial or how-to (S1), and a tutorial's questions, objectives and key points (S2), as the file states them.
    howtoType: /** @type {keyof typeof HOWTO_TYPES | null} */ (d.profile === "computational" && Object.hasOwn(HOWTO_TYPES, d.type) ? d.type : null),
    questions: await inlineList(d.questions),
    objectives: await inlineList(d.objectives),
    keyPoints: await inlineList(d.key_points),
    explanation: list(known(d.explanation)).map((/** @type {any} */ e) => ({ title: String(e.title), url: String(e.url) })),
    environmentHtml: await md(d.environment),
    prerequisites: /** @type {string[]} */ (
      (await Promise.all(list(known(d.prerequisites)).map((/** @type {string} */ p) => md(p, { inline: true })))).filter(Boolean)
    ),
    gaps,
  };
  return record;
}

/** @typedef {Awaited<ReturnType<typeof renderProcedure>>} ProcedureRecord */

/**
 * The scale factor a request asks for, or 1. A protocol scales its material totals by the count of its
 * unit; a recipe scales its step amounts by servings.
 *
 * @param {ProcedureRecord} record
 * @param {number | null} asked the count (protocol) or servings (recipe) in the URL
 */
export function scaleFactor(record, asked) {
  if (!asked || !(asked > 0) || asked > 1000) return 1;
  if (record.profile === "recipe" && record.servings) return asked / record.servings;
  if (record.profile === "protocol" && record.scale) return asked / record.scale.count;
  return 1;
}

/**
 * The step's HTML with its quantity slots filled. A protocol's step amounts are per unit and never
 * scale; a recipe's scale unless the file fixed them.
 *
 * @param {{ html: string | null, quantities: Array<{ name?: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }> }} step
 * @param {number} factor
 * @param {(q: { name?: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }) => string} [show] how a recipe shows an amount in the reader's units (recipe-views.mjs)
 */
export function fillQuantities(step, factor, show) {
  return (step.html ?? "").replace(SLOT_PATTERN, (_all, i) => {
    const q = step.quantities[Number(i)];
    if (!q) return "";
    return show ? show(q) : formatQuantity({ ...q, raw: "" }, factor);
  });
}

/**
 * The markdown twin: the same facts as the page, generated from the same file.
 *
 * @param {ProcedureRecord} record
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 */
export function procedureMarkdown(record, parsed) {
  const d = parsed.data;
  const out = [`# ${record.title}`, "", record.description, ""];
  const facts = [
    ["Type", record.howtoType ? HOWTO_TYPES[record.howtoType] : null],
    ["Version", record.version],
    ["Updated", record.updated],
    ["First used", record.firstUsed],
    ["Last run", record.lastRun],
    ["Status", record.status],
    ["Scale", record.scale ? `${record.scale.count} ${record.scale.unit}${record.scale.count === 1 ? "" : "s"}` : null],
    ["Servings", record.servings],
    ["Prep time", record.prepTime],
    ["Cook time", record.cookTime],
    ["Total time", record.time.total],
    ["Hands-on time", record.time.handsOn],
    // The parent's file name and version; the twin's route reads it out as the parent's title and address (lineage.mjs).
    ["Based on", record.forkedFrom ? storedLineage(record.forkedFrom) : null],
    ["Host strain", record.hostStrains.length > 0 ? record.hostStrains.map((s) => `[${s.name}](${s.path})`).join("; ") : null],
    ["Biosafety level", record.biosafetyLevel],
    [
      "Biosafety",
      record.biosafety
        ? [record.biosafety.organism, record.biosafety.strain, record.biosafety.atcc ? `ATCC ${record.biosafety.atcc}` : null]
            .filter(Boolean)
            .join(", ")
        : null,
    ],
  ].filter(([, v]) => v !== null && v !== undefined && v !== "");
  for (const [k, v] of facts) out.push(`- ${k}: ${v}`);
  if (facts.length) out.push("");
  // A tutorial opens with what it answers and teaches (S2), as the page does.
  const bullets = (/** @type {string} */ title, /** @type {unknown} */ value) => {
    const items = list(known(value));
    if (items.length) out.push(`## ${title}`, "", ...items.map((x) => `- ${x}`), "");
  };
  bullets("Questions", d.questions);
  bullets("Objectives", d.objectives);
  if (parsed.intro) out.push(parsed.intro, "");

  if (record.basedOn.length) {
    out.push("## Based on", "");
    for (const s of record.basedOn) {
      const link = s.doi ? ` (doi:${s.doi})` : s.url ? ` (${s.url})` : "";
      out.push(`- ${s.citation}${link}: ${s.for}`);
    }
    out.push("");
  }

  const heading = record.profile === "recipe" ? "Ingredients" : record.profile === "computational" ? "Software and data" : "Reagents";
  out.push(`## ${heading}`, "");
  // The registry reagents the materials name, as the record baked them (the file holds only their ids).
  const reagentOf = new Map(record.materials.map((m) => [m.name, m.reagent]));
  for (const m of list(d.materials).length ? list(d.materials) : record.materials) {
    const parts = [
      known(m.amount) ? `${m.amount}${known(m.per) ? ` per ${m.per}` : ""}` : null,
      list(m.stock).filter((s) => known(s) !== null).length ? `stock ${list(m.stock).filter((s) => known(s) !== null).join(" or ")}` : null,
      known(m.final) ? `final ${m.final}` : null,
      known(m.version) ? `version ${m.version}` : null,
    ].filter(Boolean);
    const note = known(m.note) ? ` ${m.note}` : "";
    const reagent = reagentOf.get(m.name) ?? null;
    const shown = m.display ?? reagent?.name ?? m.name;
    if (reagent) {
      const source = reagentSource(reagent);
      parts.push(source.href ? `source [${source.text}](${source.href})` : `source ${source.text}`);
    }
    // A published reagent links its page, as the page's table does.
    const named = reagent?.status === "published" ? `[${shown}](${itemPath("reagent", reagent.id)})` : shown;
    out.push(`- ${named}${m.group ? ` (${m.group})` : ""}${parts.length ? `: ${parts.join("; ")}.` : ""}${note}`);
  }
  out.push("");
  for (const s of record.solutions) {
    out.push(`### ${s.name}`, "");
    for (const c of s.components) out.push(`- ${c.name}${c.final ? `, ${c.final} final` : ""}${c.amount ? `, ${c.amount}` : ""}`);
    if (s.storage) out.push(`- Storage: ${s.storage}`);
    if (s.shelfLife) out.push(`- Shelf life: ${s.shelfLife}`);
    out.push("");
  }
  if (record.equipment.length) {
    out.push("## Equipment", "");
    // The registry facts of each item, as the record baked them (the file holds only the ids).
    const itemOf = new Map(record.equipment.map((e) => [e.name, e.item]));
    for (const e of list(d.equipment)) {
      const name = typeof e === "string" ? e : String(e.name);
      const item = itemOf.get(name) ?? null;
      const facts = item ? ` (${[`manufacturer ${item.manufacturer ?? "not recorded"}`, item.rotor ? `rotor ${item.rotor}` : item.rotorGap ? "rotor not recorded" : null].filter(Boolean).join("; ")})` : "";
      const named = item?.status === "published" ? `[${name}](${itemPath("equipment", item.id)})` : name;
      out.push(`- ${named}${facts}${typeof e === "string" || !e.note ? "" : `: ${e.note}`}`);
    }
    out.push("");
  }
  if (record.primers.length) {
    const products = productsForRows(record.primers);
    out.push("## Primers", "", "| Primer | Direction | Sequence (5′ to 3′) | Product (computed) |", "| --- | --- | --- | --- |");
    for (const p of record.primers) {
      const pair = products.get(p.id);
      const sizes = pair ? [...new Set(pair.products.map((x) => x.length))].map((n) => `${n} bp`).join(" or ") : "";
      out.push("| [" + p.name + "](/research/lab/primers/" + p.id + ") | " + (p.direction ?? "") + " | " + (p.sequence ? "`" + p.sequence + "`" : "") + " | " + sizes + " |");
    }
    out.push("");
    const references = [...new Set([...products.values()].map((pair) => pair.reference.id))];
    if (references.length > 0) out.push(`Product sizes are computed from where the primers bind ${references.join(", ")}, in that accession's coordinates.`, "");
  }
  out.push(...keyResourcesMarkdown(keyResources(record)));
  if (known(d.environment)) out.push("## Environment", "", String(d.environment), "");
  if (record.prerequisites.length) out.push("## Prerequisites", "", ...list(d.prerequisites).map((p) => `- ${p}`), "");

  for (const section of parsed.sections) {
    out.push(`## ${section.title}`, "");
    for (const block of section.blocks) {
      if (block.type === "prose") {
        out.push(block.markdown, "");
        continue;
      }
      for (const step of block.steps) {
        out.push(`${step.number}. ${step.segments.map((s) => segmentText(s)).join("")}`);
        const flag = (/** @type {string} */ name, /** @type {string[]} */ items) => {
          for (const item of items) if (!GAP.test(item)) out.push(`   > ${name}: ${item.replace(/\n/g, "\n   > ")}`);
        };
        flag("Critical", step.flags.critical);
        flag("Pause point", step.flags.pause);
        flag("Spin", step.flags.spin);
        flag("Why", step.flags.why);
        flag("Expected", step.flags.expect);
        for (const id of step.flags.troubleshooting) out.push(`   > Troubleshooting: see "${id}" below.`);
        for (const c of readCalcs(step.flags.calc)) out.push(`   > Calculator: [${TOOLS[c.id]?.title}](${TOOLS[c.id]?.path})${Object.keys(c.values).length ? ` with ${Object.entries(c.values).map(([k, v]) => `${k} ${v}`).join(", ")}` : ""}`);
        // Every platform's block, each under its name (S4): the page's tabs are a view of these.
        for (const cmd of step.commands) {
          if (cmd.platform) out.push("", `   ${PLATFORMS[/** @type {keyof typeof PLATFORMS} */ (cmd.platform)] ?? cmd.platform}:`);
          out.push("", `   \`\`\`${cmd.lang}`, ...cmd.code.split("\n").map((l) => `   ${l}`), "   ```");
          if (cmd.output !== null) {
            out.push("", "   Expected output:", "", "   ```", ...cmd.output.split("\n").map((l) => `   ${l}`), "   ```");
          }
        }
        for (const p of step.photos) out.push(`   ![${p.alt}](${p.src})`);
        // A challenge and its solution, both: the page folds the solution away, and a machine reads it anyway.
        step.flags.challenge.forEach((c, i) => {
          out.push("", `   > Challenge: ${c.replace(/\n/g, "\n   > ")}`);
          const solution = step.flags.solution[i];
          if (solution) out.push("", `   > Solution: ${solution.replace(/\n/g, "\n   > ")}`);
        });
      }
      out.push("");
    }
  }

  bullets("Key points", d.key_points);
  if (record.explanation.length) out.push("## Explanation", "", ...record.explanation.map((e) => `- [${e.title}](${e.url})`), "");

  if (list(d.troubleshooting).length) {
    out.push("## Troubleshooting", "", "| Step | Problem | Possible reason | Solution |", "| --- | --- | --- | --- |");
    for (const r of list(d.troubleshooting)) {
      const cell = (/** @type {unknown} */ v) => String(v).replace(/\|/g, "\\|").replace(/\n/g, " ");
      out.push(`| ${cell(r.step)} | ${cell(r.problem)} | ${cell(r.reason)} | ${cell(r.solution)} |`);
    }
    out.push("");
  }
  if (known(d.expected_results)) out.push("## Expected results", "", String(d.expected_results), "");
  if (known(d.limitations)) out.push("## Limitations", "", String(d.limitations), "");
  if (list(d.substitutions).length) {
    out.push("## Substitutions", "");
    for (const s of list(d.substitutions)) out.push(`- For ${s.for}, use ${s.use}${s.note ? `: ${s.note}` : ""}`);
    out.push("");
  }
  if (record.history.length) {
    out.push("## Version history", "");
    for (const h of list(d.history)) out.push(`- Version ${h.version}, ${h.date}: ${h.summary}${h.doi ? ` (doi:${h.doi})` : ""}`);
    out.push("");
  }
  const refs = list(known(d.references));
  if (refs.length) out.push("## References", "", ...refs.map((r) => `- ${r}`), "");
  return `${out.join("\n").replace(/\n{3,}/g, "\n\n").trim()}\n`;
}

/**
 * The search uid of the page at `path`: the one the page had when it was a content page, so a search
 * link survives the move. Also what removing a procedure's search records is keyed by.
 *
 * @param {string} path
 */
export function procedureSearchUid(path) {
  return `page:${path.slice(1).replaceAll("/", ":")}`;
}

/**
 * What the search index takes for this procedure, in the shape recordsForPages reads, with the uid
 * `procedureSearchUid` names.
 *
 * @param {ProcedureRecord} record
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 */
export function procedureSearchInput(record, parsed) {
  const markdown = procedureMarkdown(record, parsed);
  const sections = parsed.sections.map((section) => {
    const body = section.blocks
      .map((block) =>
        block.type === "prose"
          ? block.markdown
          : block.steps
              .map((s) => [s.segments.map((x) => segmentText(x)).join(""), ...s.flags.why, ...s.flags.critical].join(" "))
              .join(" "),
      )
      .join(" ");
    return { anchor: section.id, title: section.title, body: plainText(body) };
  });
  return {
    url: record.path,
    uid: procedureSearchUid(record.path),
    title: record.title,
    description: record.description,
    intro: plainText(parsed.intro),
    sections,
    markdown,
  };
}

app/kb/registry/equipment.mjs.source:
// The equipment kind of the lab registry (docs/REGISTRY.md): the instruments and labware the lab's protocols list under
// Equipment. Like the reagents, the equipment is one table (the library's Equipment tab) with a page for each item that lists the
// protocols using it (docs/KNOWLEDGE-BASE.md, A1), and each protocol's own Equipment table is drawn from these records beside the
// protocol's own words for the item.
//
// A record states what the lab's own pages state about one item: its name and who makes it, which is `MISSING: <why>` where no
// record in the repository says and is listed for Dustin. A centrifuge also carries the rotor its speeds are read for, which is
// Dustin's to name (core.md: the ZnCl2 rotor), so it is recorded as a gap and the protocols' rpm cannot yet be given as x g.
//
// What the protocols do with an item is the PROTOCOLS' and is never stored here: a protocol lists it under its own words (55 °C
// water bath for molten top agar, plate incubator at 29 °C for M. foliorum) and names the record with `equipment: <id>`, so the
// setting is the protocol's own and the table lists the protocols that name it.

const LINE = /^[^\r\n]+$/;

/** @param {unknown} value @param {number} max */
const oneLine = (value, max) =>
  typeof value === "string" && LINE.test(value) && value === value.trim() && value.length <= max ? null : `is one line of at most ${max} characters`;

/** @type {import("./kinds.mjs").KindSpec} */
export const EQUIPMENT = {
  singular: "equipment",
  plural: "equipment",
  fields: {
    manufacturer: { required: true, check: (value) => oneLine(value, 80) },
    // The rotor a centrifuge's speeds are read for: a protocol gives rpm, and x g needs the rotor (core.md: waiting on Dustin).
    rotor: { check: (value) => oneLine(value, 120) },
  },
};

/**
 * An equipment item as a protocol carries it (`StoredEquipment` in app/kb/procedures/render.mjs): the registry's stated facts, none
 * computed, so the protocol's Equipment table, twin and frozen versions say who makes each as it was when the protocol was published.
 * `rotorGap` is whether a rotor is recorded as missing, so a centrifuge's table says so rather than leaving it blank.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {import("../procedures/render.mjs").StoredEquipment}
 */
export function storedEquipment(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  const text = (/** @type {unknown} */ value) => (typeof value === "string" && value !== "" && !value.startsWith("MISSING") ? value : null);
  return {
    id: item.id,
    name: item.name,
    status: item.status,
    manufacturer: text(f.manufacturer),
    rotor: text(f.rotor),
    rotorGap: typeof f.rotor === "string" && f.rotor.startsWith("MISSING"),
  };
}

app/kb/registry/strain.mjs.source:
// The strain kind of the lab registry (docs/REGISTRY.md): the bacterial hosts the lab's phage work grows. A strain record
// states what the lab's own pages state about one host (its organism, the strain designation where it has one, the culture
// collection and the number the collection gives it, the SEA-PHAGES Guide's page for it) and the biosafety level, which is
// Dustin's to set and is MISSING until the biosafety officer check is done (core.md).
//
// The strain's id is the phages' host key (app/lib/phages/compile.mjs HOSTS), so a phage's host and a strain are one word,
// and what follows from it is COMPUTED: the phages isolated on the host are read from the phages table, the protocols that use
// the strain are read from the protocols (which name their host strains by id), and the strain's full name is its organism and
// designation, which the record's `name` must equal.

import { BIOSAFETY_LEVELS } from "../procedures/validate.mjs";
import { stated } from "./primer.mjs";

const LINE = /^[^\r\n]+$/;

/** @param {unknown} value @param {number} max */
const oneLine = (value, max) =>
  typeof value === "string" && LINE.test(value) && value === value.trim() && value.length <= max ? null : `is one line of at most ${max} characters`;

/** @type {import("./kinds.mjs").KindSpec} */
export const STRAIN = {
  singular: "strain",
  plural: "strains",
  fields: {
    organism: { required: true, check: (value) => oneLine(value, 120) },
    // The lab's designation within the species, where there is one apart from the collection's number (mc²155).
    strain: { check: (value) => oneLine(value, 60) },
    collection: { required: true, check: (value) => oneLine(value, 60) },
    collection_number: { required: true, check: (value) => oneLine(value, 40) },
    guide_url: { check: (value) => (typeof value === "string" && /^https:\/\/[^\s]+$/.test(value) ? null : "is an https address") },
    // Dustin's to set: a gap until the biosafety officer check is done.
    biosafety_level: {
      required: true,
      check: (value) => (BIOSAFETY_LEVELS.includes(/** @type {any} */ (value)) ? null : `is one of ${BIOSAFETY_LEVELS.join(", ")}, or "MISSING: <why>" until Dustin sets it`),
    },
  },
  /** The name is the organism and its designation, so it is stated once and cannot say a different strain than the fields do. */
  setErrors(items) {
    /** @type {string[]} */
    const errors = [];
    for (const { id, name, fields } of items) {
      const organism = stated(fields.organism);
      const designation = designationOf(fields);
      if (organism && designation && name !== `${organism} ${designation}`) {
        errors.push(`strain/${id} is named "${name}", but its organism and designation make "${organism} ${designation}"; the name is computed from them`);
      }
    }
    return errors;
  },
};

/**
 * How the strain is designated: the lab's own designation where there is one, otherwise the collection and its number.
 *
 * @param {Record<string, unknown>} fields
 */
export function designationOf(fields) {
  const strain = stated(fields.strain);
  if (strain) return strain;
  const collection = stated(fields.collection);
  const number = stated(fields.collection_number);
  return collection && number ? `${collection} ${number}` : null;
}

/**
 * A strain as a protocol carries it (`StoredStrain` in app/kb/procedures/render.mjs): the stated facts, none computed, so the
 * protocol's page, twin and frozen versions name one strain.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {import("../procedures/render.mjs").StoredStrain}
 */
export function storedStrain(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return {
    id: item.id,
    name: item.name,
    status: item.status,
    organism: stated(f.organism),
    strain: stated(f.strain),
    collection: stated(f.collection),
    collectionNumber: stated(f.collection_number),
  };
}

app/lib/carrel/content-id.mjs.source:
// The one place a content kind and its slug become a site-api content id and back. site-api's ContentId
// is `^[A-Za-z0-9][A-Za-z0-9._-]{0,199}$` (no colon), so the separator is a dot. Pure, so the publication
// validator can share the length rule with the registry (content-kinds.server.ts).

/** The contract's ContentId allows at most 200 characters (site-api contract.ts). */
const CONTENT_ID_MAX = 200;

/** The kind that keeps a bare slug for its id, so every id posts already had is unchanged. */
export const DEFAULT_KIND = "post";

/** The separator between a kind and a slug. A bare id has none; a slug may itself contain it. */
const SEPARATOR = ".";

/**
 * The contract id for a kind's slug: posts keep the bare slug, every other kind is `<kind>.<slug>`.
 *
 * @param {string} kind
 * @param {string} slug
 */
export function encodeContentId(kind, slug) {
  return kind === DEFAULT_KIND ? slug : `${kind}${SEPARATOR}${slug}`;
}

/**
 * The kind and slug of a contract id. A post slug never contains the separator (SLUG_PATTERN), so an id
 * with none is a post; otherwise the kind is everything before the FIRST separator and the slug is the rest.
 *
 * @param {string} id
 * @returns {{ kind: string, slug: string }}
 */
export function decodeContentId(id) {
  const at = id.indexOf(SEPARATOR);
  if (at === -1) return { kind: DEFAULT_KIND, slug: id };
  return { kind: id.slice(0, at), slug: id.slice(at + 1) };
}

/**
 * Whether `<kind>.<slug>` fits the contract's id length, for a validator to refuse a slug that cannot.
 *
 * @param {string} kind
 * @param {string} slug
 */
export function contentIdFits(kind, slug) {
  return encodeContentId(kind, slug).length <= CONTENT_ID_MAX;
}

app/lib/content-pages.mjs.source:
/**
 * The Research, Teaching and Software pages: markdown in content/pages/, rendered at build time into
 * content/generated/pages.json like the About page, and served by one route module. This list is the
 * one place their paths are named: app/routes.ts registers a route per entry, the sitemap lists each,
 * and the build refuses a markdown file whose path is not here or an entry with no file.
 *
 * The 2026-09-27 cutover wrote them from the old WordPress site, its knowledge base and the lab's
 * notebooks (cutover.md, "Pages to build before the switch").
 */

import { ogImageKey } from "./content/og-card-text.mjs";
import { dictionaryEntryMarkdown, dictionaryEntryText } from "./dictionary-entries.mjs";
import { longDateUTC } from "./long-date.mjs";
import { splitSections } from "./search/records.mjs";

export const CONTENT_PAGE_PATHS = /** @type {const} */ ([
  "/research",
  "/research/retroviruses",
  "/research/retroviruses/human",
  "/research/retroviruses/avian",
  "/research/bacteriophages",
  "/research/science-education",
  "/research/phages",
  // Not in cutover.md's page list, but its redirect rows land old knowledge-base addresses here.
  "/research/protocols",
  // The protocols themselves are procedures (content/procedures/, docs/PROCEDURES.md), drawn from D1.
  // The phage lab calculators (job_c2b88d76b3c1). Their addresses are fixed: the citable version
  // (Zenodo DOI, JMBE) replaces them in place, so none of these may move.
  "/research/tools",
  "/research/tools/titer",
  "/research/tools/dilution",
  "/research/tools/webbed-plate",
  "/research/tools/moi",
  "/research/tools/eop",
  "/research/tools/lysate-volume",
  "/teaching",
  "/teaching/phage-discovery",
  "/teaching/virus-isolation",
  "/teaching/virus-isolation/faq",
  "/teaching/phage-bioinformatics",
  "/teaching/central-dogma",
  "/teaching/study-skills",
  "/software",
  "/software/foxhound",
  "/software/foxing",
  "/software/foxing-edu",
  "/software/germomics",
  "/software/capsid",
  "/software/enarratio",
  "/software/carrel",
  "/software/capsomer",
  // The CV. Its entries are the files in content/cv/ (docs/CV.md), not a markdown page kept in content/pages/.
  "/cv",
  // The legal pages, in Carrel with the rest (job_044f96426efa). /terms is also the terms the site's data is
  // published under: the `license` of every Dataset (app/lib/license.mjs).
  "/privacy",
  "/terms",
  // The accessibility statement (job_fea2f94832b3): what the gates check, in Carrel with the legal pages but
  // not one of them. It ships as a draft until Dustin approves its text, and the footer links it once published.
  "/accessibility",
]);

/**
 * The legal pages: the only ones whose front matter may state a `banner` (the one word "Draft") and a
 * `last_updated` date, which the layout draws for every reader and the markdown twin repeats. Carrel writes
 * both (carrel design-legal-pages.md).
 *
 * @type {readonly string[]}
 */
export const LEGAL_PAGE_PATHS = ["/privacy", "/terms"];

/** The one word a legal page's `banner` may say. */
export const LEGAL_BANNER = "Draft";

/**
 * The listed pages whose markdown is GENERATED from structured data rather than read from
 * content/pages/: build:content renders it from app/lib/cv/markdown.mjs, so the twin, sitemap, search
 * records and llms.txt treat /cv like every other page. Their HTML comes from their own route
 * (app/routes/cv.tsx) and their twin from another (app/routes/cv[.md].ts), both drawn from the cv table, so
 * pages.json and the pages table leave them out.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_FROM_DATA = ["/cv"];

/**
 * The listed pages a reader can open: every one whose page is published, and the ones generated from data.
 * llms.txt must list each of these. `published` is the published paths from whichever source the caller
 * judges against: the page files (readPublishedPages()) in CI and the gates, the D1 rows in the llms.txt save.
 *
 * @param {readonly string[]} published
 * @returns {string[]}
 */
export function publishedContentPagePaths(published) {
  return CONTENT_PAGE_PATHS.filter((path) => CONTENT_PAGES_FROM_DATA.includes(path) || published.includes(path));
}

/**
 * The listed pages that are drafts: llms.txt may name them (so a page's line can land before or after it is
 * published, in either order) but need not.
 *
 * @param {readonly string[]} published as for publishedContentPagePaths
 * @returns {string[]}
 */
export function draftContentPagePaths(published) {
  const open = publishedContentPagePaths(published);
  return CONTENT_PAGE_PATHS.filter((path) => !open.includes(path));
}

/**
 * The pages that have a file in content/pages/, a row in the pages table and the page save, but whose
 * route, layout and structured data are their own (app/routes/about.tsx, a ProfilePage with its photo). They
 * are not in CONTENT_PAGE_PATHS, so the research splat, a markdown twin, a search record and the llms.txt
 * rules never see them: moving About onto D1 changed where its prose is kept and nothing a visitor reads.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_OWN_ROUTE = ["/about"];

/** Every path a file in content/pages/ may name: the listed pages and the ones with a route of their own. */
export const PAGE_FILE_PATHS = /** @type {readonly string[]} */ ([...CONTENT_PAGE_PATHS, ...CONTENT_PAGES_OWN_ROUTE]);

/**
 * The headings on these pages that the header menus link to by anchor, as `path#id`. A menu shows a
 * section link only once it is listed here, and the build refuses an entry whose page has no heading
 * with that id, so no menu link lands on the top of a page for want of its heading.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGE_SECTIONS = ["/teaching#join-the-lab", "/teaching#teaching-philosophy"];

/**
 * The markdown file a path is written in: slashes to hyphens, `/research/phages` in research-phages.md.
 *
 * @param {string} path
 */
export function contentPageFile(path) {
  return `${path.slice(1).replaceAll("/", "-")}.md`;
}

/**
 * The markdown twin's URL: the page path plus `.md`. Not `contentPageFile`, which is the repo filename.
 *
 * @param {string} path
 */
export function contentPageMarkdownPath(path) {
  return `${path}.md`;
}

/**
 * The twin a machine reads. The HTML page's h1 is not in the source body, so the title is the first line,
 * followed by the page's dictionary entry where it has one, where the page shows it. The entry is the
 * caller's to give: the build reads it from content/dictionary, the Worker from D1 (docs/DICTIONARY.md).
 *
 * @param {{ path?: string, title: string, markdown: string, banner?: string, lastUpdated?: string }} page
 * @param {import("./dictionary-entries.mjs").DictionaryEntry} [entry] the page's published entry, if any
 */
export function contentPageMarkdownBody(page, entry) {
  const body = String(page.markdown ?? "").replace(/^\n+/, "");
  const lead = entry ? `${dictionaryEntryMarkdown(entry)}\n` : "";
  // A legal page's banner and date are facts a reader sees under the title, so the twin states them too.
  const stated = [page.banner, page.lastUpdated ? `Last updated: ${longDateUTC(page.lastUpdated)}` : ""].filter(Boolean);
  const legal = stated.length > 0 ? `${stated.join("\n\n")}\n\n` : "";
  return `# ${page.title}\n\n${legal}${lead}${body}`;
}

/**
 * The pages build:og draws a social card of their own, by the root they sit under: the root and every
 * page below it, so a calculator added under /research/tools is carded with no edit here. Every other
 * page keeps the site card. Adding a root cards its pages on the next build:og.
 *
 * @type {readonly string[]}
 */
export const CARDED_PAGE_ROOTS = ["/software", "/research/tools", "/cv"];

/** @param {string} path */
export function hasPageCard(path) {
  return CARDED_PAGE_ROOTS.some((root) => path === root || path.startsWith(`${root}/`));
}

/**
 * What build:og draws for a page, in the shape ogImageKey hashes: the page's og:title (its SERP title)
 * and its description, with no date line, since these pages are not dated. The `page-` prefix keeps a
 * page's key apart from a post's, and build:og refuses two cards with one key.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 */
export function contentPageCardInput(page) {
  return {
    slug: `page-${page.path.slice(1).replaceAll("/", "-")}`,
    title: page.seoTitle,
    description: page.description,
    publishAt: null,
  };
}

/**
 * The /media path of a page's card, which its og:image names, or null for a page on the site card. The
 * key hashes what the card draws, so a retitled page names a new card, which build:og then draws.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 * @returns {string | null}
 */
export function contentPageCardPath(page) {
  return hasPageCard(page.path) ? `/media/${ogImageKey(contentPageCardInput(page))}` : null;
}

/**
 * What a Dataset node says about a page's first markdown table, read from the markdown the page renders:
 * its column headings, as the variables, and the span of its Year column, as an ISO 8601 interval. Null
 * when the page has no table.
 *
 * @param {string} markdown
 * @returns {{ variableMeasured: string[], temporalCoverage: string | null, rows: number } | null}
 */
export function markdownTableFacts(markdown) {
  const lines = String(markdown ?? "").split("\n");
  const rule = /^\|(\s*:?-+:?\s*\|)+\s*$/;
  const at = lines.findIndex((line, i) => /^\|.*\|\s*$/.test(line) && rule.test(lines[i + 1] ?? ""));
  if (at < 0) return null;
  const cells = (/** @type {string} */ line) =>
    line
      .trim()
      .replace(/^\||\|$/g, "")
      .split("|")
      .map((cell) => cell.trim());
  const headings = cells(lines[at] ?? "");
  /** @type {string[][]} */
  const rows = [];
  for (let i = at + 2; i < lines.length && (lines[i] ?? "").startsWith("|"); i += 1) rows.push(cells(lines[i] ?? ""));
  const yearColumn = headings.findIndex((heading) => /^year$/i.test(heading));
  const years =
    yearColumn < 0
      ? []
      : rows.map((row) => Number(row[yearColumn])).filter((year) => Number.isInteger(year) && year > 0);
  const first = Math.min(...years);
  const last = Math.max(...years);
  const temporalCoverage = years.length === 0 ? null : first === last ? String(first) : `${first}/${last}`;
  return { variableMeasured: headings, temporalCoverage, rows: rows.length };
}

/** Google clips near these; the build refuses longer ones rather than ship a clipped result. */
export const SEO_TITLE_MAX = 60;
export const DESCRIPTION_MAX = 155;

/** The hubs, and the trail label each gives the pages under it. */
const HUBS = /** @type {const} */ ([
  ["/research", "Research"],
  ["/teaching", "Teaching"],
  ["/software", "Software"],
]);

/**
 * The trail above a page: its hub, the page it sits under when it is three deep (the course above its
 * FAQ), then the page itself. A hub stands alone.
 *
 * @param {{ path: string, title: string }} page
 * @param {(path: string) => string | undefined} [titleOf] the title of another listed page
 * @returns {Array<[string, string]>}
 */
export function contentPageTrail(page, titleOf = () => undefined) {
  const hub = HUBS.find(([path]) => page.path.startsWith(`${path}/`));
  if (!hub) return [[page.title, page.path]];
  const trail = /** @type {Array<[string, string]>} */ ([[hub[1], hub[0]]]);
  const parent = page.path.slice(0, page.path.lastIndexOf("/"));
  const parentTitle = parent !== hub[0] ? titleOf(parent) : undefined;
  if (parentTitle) trail.push([parentTitle, parent]);
  trail.push([page.title, page.path]);
  return trail;
}

/** The search uid of a page path: a removal needs it to find the page's records. */
export function contentPageSearchUid(/** @type {string} */ path) {
  return `page:${path.slice(1).replaceAll("/", ":")}`;
}

/**
 * Search inputs in the shape `recordsForPages` takes: one record for the page, one per heading, each
 * deep-linking to the heading's own anchor.
 *
 * @param {Array<{ path: string, title: string, description: string, markdown: string, toc: Array<{ depth: number, id: string, text: string }> }>} pages
 * @param {(path: string) => import("./dictionary-entries.mjs").DictionaryEntry | undefined} [entryFor] the
 *   published dictionary entry of a page path, which leads that page's record
 */
export function contentPageSearchInputs(pages, entryFor = () => undefined) {
  return pages.map((page) => {
    const { intro, sections } = splitSections(page.markdown, page.toc);
    const entry = entryFor(page.path);
    return {
      url: page.path,
      uid: contentPageSearchUid(page.path),
      title: page.title,
      description: page.description,
      intro: entry ? `${dictionaryEntryText(entry)} ${intro}` : intro,
      sections: sections.map(({ anchor, title, body }) => ({ anchor, title, body })),
    };
  });
}

