/**
 * NUL cannot occur in any part, so the join is unambiguous; a printable `|`
 * would collide ("a|b","c" vs "a","b|c") and silently drop a ref. Keep it an
 * escape: a literal NUL makes the file binary to git and invisible in editors.
 *
 * @param {{ mediaKey: string, form: string, detail: string | null }} ref
 * @returns {string}
 */
export function mediaRefKey(ref) {
  return `${ref.mediaKey}\u0000${ref.form}\u0000${ref.detail ?? ""}`;
}

app/lib/media/tags.mjs.source:
// A column, not a join table like posts: media tags have no public page, and search stays one LIKE chain.
// Stored DELIMITER-WRAPPED (`,alpha,beta,`) so an exact match is `LIKE '%,art,%'` and misses `chart`;
// the empty list is "" so an untagged row cannot match `%,%`.

const TAG_DELIMITER = ",";

export const MAX_TAG_LENGTH = 32;

export const MAX_TAGS = 12;

/**
 * @param {unknown} raw
 * @returns {string}
 */
export function normalizeTag(raw) {
  if (typeof raw !== "string") return "";
  return raw
    .toLowerCase()
    .split(TAG_DELIMITER)
    .join(" ")
    .trim()
    .replace(/\s+/g, "-")
    // Never a `%` or `_`: they are LIKE wildcards and would turn a stored value into a pattern.
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_TAG_LENGTH)
    .replace(/-+$/, "");
}

/**
 * Sorted so the same set always stores the same bytes, whatever the typing order.
 *
 * @param {unknown} input
 * @returns {string[]}
 */
export function normalizeTags(input) {
  const parts = Array.isArray(input)
    ? input
    : typeof input === "string"
      ? input.split(TAG_DELIMITER)
      : [];
  const seen = new Set();
  for (const part of parts) {
    const tag = normalizeTag(part);
    if (tag) seen.add(tag);
  }
  return [...seen].sort().slice(0, MAX_TAGS);
}

/**
 * @param {unknown} input
 * @returns {string}
 */
export function serializeTags(input) {
  const tags = normalizeTags(input);
  if (tags.length === 0) return "";
  return `${TAG_DELIMITER}${tags.join(TAG_DELIMITER)}${TAG_DELIMITER}`;
}

/**
 * @param {unknown} stored
 * @returns {string[]}
 */
export function parseTags(stored) {
  if (typeof stored !== "string" || stored === "") return [];
  return normalizeTags(stored);
}

/**
 * Null means "no filter", never a needle: `%,,%` would match every tagged row.
 *
 * @param {unknown} raw
 * @returns {string | null}
 */
export function exactTagNeedle(raw) {
  const tag = normalizeTag(raw);
  if (!tag) return null;
  return `%${TAG_DELIMITER}${tag}${TAG_DELIMITER}%`;
}

app/lib/pages/links.mjs.source:
// The internal links of a page, judged at save time. check:links is CI's full gate over every link the
// site publishes, built from the repository's sources; a save through the operator API is live before CI
// runs, so the part of that judgment a Worker can make from D1 and code is made here, with the same
// gateway functions the router uses (docs/PAGES.md).
//
// It refuses only what it can PROVE broken: a link into a namespace this module can list completely
// (the Research, Teaching, Software and recipe pages, the procedures, the posts) that names nothing in
// it, a path the gateway answers 410, a draft post, and an anchor missing from a content page. Any other
// address passes here and is left to check:links.

import { CONTENT_PAGE_PATHS, contentPageMarkdownPath } from "../content-pages.mjs";
import { wordpressDisposition } from "../wordpress-redirects.mjs";

/**
 * @typedef {{
 *   procedurePaths: ReadonlySet<string>,
 *   posts: ReadonlyMap<string, boolean>,
 *   idsOf: (path: string) => ReadonlySet<string> | null,
 * }} AddressBook
 * `posts` maps `/writing/<slug>` to whether a reader can open it; `idsOf` is the element ids a content
 * page carries, or null for a path that is not one.
 */

const decodeEntities = (/** @type {string} */ value) =>
  value.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">");

const safeDecode = (/** @type {string} */ value) => {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

const SITE_HOST = /^https?:\/\/(?:www\.)?dustinedwards\.info(?=[/?#]|$)/i;

/** Every element id in rendered HTML. */
export function idsIn(/** @type {string} */ html) {
  return new Set([...html.matchAll(/\sid="([^"]+)"/g)].map((m) => decodeEntities(m[1] ?? "")));
}

const PAGE_SET = new Set(/** @type {readonly string[]} */ (CONTENT_PAGE_PATHS));
const PAGE_TWINS = new Set(CONTENT_PAGE_PATHS.map((p) => contentPageMarkdownPath(p)));

/** The namespaces this module can list completely. */
const OWNED = /^\/(?:research|teaching|software|recipes|writing)(?:\/|$)/;
/** Listed elsewhere: papers and citation exports, feeds, tag and series pages. */
const NOT_LISTED = /^\/(?:research\/publications|writing\/(?:tags|series|rss\.xml|feed\.json|atom\.xml))(?:[/.]|$)/;

/**
 * @param {string} path
 * @param {AddressBook} book
 * @param {number} [hops]
 * @returns {{ kind: "ok" | "unlisted" | "gone" | "draft" | "missing", path: string }}
 */
function resolve(path, book, hops = 0) {
  if (hops > 5) return { kind: "missing", path };
  const redirect = wordpressDisposition(path);
  if (redirect?.status === 410) return { kind: "gone", path };
  if (redirect?.status === 301) return resolve(redirect.location.split("#")[0] ?? "", book, hops + 1);
  if (!OWNED.test(path) || NOT_LISTED.test(path)) return { kind: "unlisted", path };
  if (PAGE_SET.has(path) || PAGE_TWINS.has(path)) return { kind: "ok", path };
  const procedure = path.replace(/(?:\.md|\/sheet)$/, "");
  if (book.procedurePaths.has(procedure)) return { kind: "ok", path };
  const visible = book.posts.get(path.replace(/\.md$/, ""));
  if (visible !== undefined) return { kind: visible ? "ok" : "draft", path };
  return { kind: "missing", path };
}

/**
 * @param {{ html: string }} page
 * @param {AddressBook} book
 * @returns {string[]}
 */
export function pageLinkErrors({ html }, book) {
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  for (const raw of [...html.matchAll(/\shref="([^"]*)"/g)].map((m) => decodeEntities(m[1] ?? ""))) {
    const href = SITE_HOST.test(raw) ? raw.replace(SITE_HOST, "") || "/" : raw;
    if (!href.startsWith("/") || href.startsWith("//") || seen.has(href)) continue;
    seen.add(href);
    const [pathAndQuery = "", anchor] = href.split("#");
    const path = (pathAndQuery.split("?")[0] ?? "").replace(/(.)\/+$/, "$1");
    const found = resolve(path, book);
    if (found.kind === "gone") errors.push(`the link ${href} goes to ${path}, which the site answers 410 Gone`);
    else if (found.kind === "draft") errors.push(`the link ${href} goes to a draft or scheduled post, which every reader gets a 404 for`);
    else if (found.kind === "missing") errors.push(`the link ${href} goes to ${found.path}, which this site does not serve`);
    else if (found.kind === "ok" && anchor && found.path === path) {
      const ids = book.idsOf(found.path);
      if (ids && !ids.has(safeDecode(anchor))) errors.push(`the link ${href} names an anchor that ${found.path} does not have`);
    }
  }
  return errors;
}

app/lib/post-order.mjs.source:
// The order posts are listed in, newest first, as one rule for the two places that apply it: the D1 listing
// queries (app/db/posts.ts, newestFirstOrder) and the header's build-time list (scripts/lib/nav-data.mjs).
//
// 1. Publish instant, latest first.
// 2. Posts that share an instant: a series stays together and reads latest part first (the newest part of a
//    series is its newest post). A series sits among unrelated posts where its latest row would.
// 3. Otherwise the later row first. The database breaks that tie by row id; the build cannot see ids, so it
//    passes the slug, because rows are inserted in slug order (scripts/build-content.mjs).
//
// Concretely: sort by instant, then by the group key (the largest tie-break value among the posts sharing the
// instant and series, or the post's own value when it has no series), then by part, then by the tie-break
// value. That is a total order, which "part descending within a series, the tie-break otherwise" alone is not.

/**
 * @template {{ publishAt: string, series: string | null, part: number | null }} P
 * @param {P[]} posts
 * @param {(post: P) => string | number} tie the row id in a database, the slug in the build
 * @returns {P[]} a new array, newest first
 */
export function newestFirst(posts, tie) {
  /** @type {Map<string, string | number>} */
  const latest = new Map();
  const groupOf = (/** @type {P} */ p) => `${p.publishAt}\u0000${p.series}`;
  for (const p of posts) {
    if (p.series === null) continue;
    const seen = latest.get(groupOf(p));
    if (seen === undefined || tie(p) > seen) latest.set(groupOf(p), tie(p));
  }
  const key = (/** @type {P} */ p) => (p.series === null ? tie(p) : /** @type {string | number} */ (latest.get(groupOf(p))));
  const desc = (/** @type {string | number} */ a, /** @type {string | number} */ b) => (a === b ? 0 : a < b ? 1 : -1);
  return [...posts].sort(
    (a, b) => desc(a.publishAt, b.publishAt) || desc(key(a), key(b)) || desc(a.part ?? 0, b.part ?? 0) || desc(tie(a), tie(b)),
  );
}

app/lib/publications/parse.mjs.source:
// Reads a publication file (docs/PUBLICATIONS.md) into the front matter as written and the one body
// section it may carry, the extracted full text. Nothing here judges: validate.mjs does, so the check and
// the save tool read one parse.

import matter from "gray-matter";

import { yamlPlain } from "../yaml-plain.mjs";

export const PUBLICATIONS_DIR = "content/publications";

/** The repository path of a publication's file. */
export function publicationPath(/** @type {string} */ slug) {
  return `${PUBLICATIONS_DIR}/${slug}.md`;
}

/** The only heading the body may carry. Everything after it is the PDF's extracted text. */
export const FULL_TEXT_HEADING = "## Full text";

const FULL_TEXT_LINE = /^## Full text[ \t]*$/m;

/**
 * @typedef {{ data: Record<string, unknown>, fullText: string | null, problems: string[] }} ParsedPublication
 */

/**
 * @param {{ file: string, raw: string }} input
 * @returns {ParsedPublication} `fullText` is null when the file has no Full text section, and a string (possibly empty) when it has.
 */
export function parsePublication({ file, raw }) {
  /** @type {string[]} */
  const problems = [];
  /** @type {Record<string, unknown>} */
  let data = {};
  let content = "";
  try {
    // An options object, even an empty one: gray-matter caches by input when it is omitted, and a
    // cached parse is one object shared by every caller.
    const parsed = matter(raw, {});
    data = /** @type {Record<string, unknown>} */ (yamlPlain(parsed.data));
    content = parsed.content;
  } catch (error) {
    problems.push(`${file}: the front matter does not parse: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`);
    return { data, fullText: null, problems };
  }
  if (!raw.startsWith("---")) {
    problems.push(`${file}: the file must start with a --- front matter block`);
  }

  const heading = FULL_TEXT_LINE.exec(content);
  if (!heading) {
    if (content.trim() !== "") {
      problems.push(
        `${file}: the body carries text outside a "${FULL_TEXT_HEADING}" section. The abstract belongs in front matter, and the body holds only the PDF's extracted text under that heading.`,
      );
    }
    return { data, fullText: null, problems };
  }
  const before = content.slice(0, heading.index).trim();
  if (before !== "") {
    problems.push(
      `${file}: the body carries text before the "${FULL_TEXT_HEADING}" heading. The abstract belongs in front matter, and the body holds only the PDF's extracted text.`,
    );
  }
  const fullText = content.slice(heading.index + heading[0].length).trim();
  return { data, fullText, problems };
}

app/lib/roster/compile.mjs.source:
// The one door from a roster file to the cohort the site draws (docs/ROSTER.md): parse, validate, hash.
// build:content, sync:content, the gates and the adapter's roster save all call compileCohort, so a file CI
// passes is the file the save accepts and the pages draw. Pure and dependency-light, so the Worker and the
// Node scripts import the same module.
//
// The shape is the one app/data/phage-hunters.ts had and no wider: a year, a group photo that is a path
// under /phage-hunters/ with its measured size and its alt text, and the names. The validator REFUSES any
// other field, so nothing a visitor cannot already see on the roster page can enter the repository or D1.

import matter from "gray-matter";

import { gitBlobSha } from "../content/hashes.mjs";

export const ROSTER_DIR = "content/roster";

/** The repository path of a cohort's file, from its file key (the year). */
export function rosterPath(/** @type {string} */ slug) {
  return `${ROSTER_DIR}/${slug}.md`;
}

/**
 * Where the roster is drawn: the one page that carries it, and the heading id the old WordPress profile
 * paths land on (app/lib/wordpress-redirects.mjs). The route
 * places the roster by this constant, and test/roster.test.mjs holds it to the registered page paths, the
 * redirect target and the component's own heading id, so the three cannot drift apart.
 */
export const ROSTER_PAGE_PATH = "/teaching/phage-discovery";
export const ROSTER_ANCHOR = "roster";

/** The directory the cohort photographs are served from. They stay static assets, referenced by path. */
export const ROSTER_PHOTO_DIR = "/phage-hunters/";

const FIELDS = ["year", "photo", "researchers"];
const PHOTO_FIELDS = ["src", "width", "height", "alt"];
const PHOTO_SRC = /^\/phage-hunters\/[A-Za-z0-9._-]+\.webp$/;
const NAME_MAX = 80;
const ALT_MAX = 200;

/**
 * @typedef {{ src: string, width: number, height: number, alt: string }} CohortPhoto
 * @typedef {{ year: number, photo: CohortPhoto | null, researchers: string[] }} Cohort
 * @typedef {{ photo: (src: string) => Promise<boolean> }} RosterHost
 * `findWideDashes` is injected, as the page compile injects the pipeline's: the Worker loads it lazily.
 * @typedef {{ findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> }} RosterPipeline
 */

/** Newest cohort first: the order the page lists them and the order the files are read in. */
export function sortCohorts(/** @type {Cohort[]} */ cohorts) {
  return [...cohorts].sort((a, b) => b.year - a.year);
}

/**
 * The home page's counts: counted, never typed. The names stay out of what the home page sends.
 *
 * @param {Cohort[]} cohorts
 * @returns {{ researchers: number, cohorts: number, since: number }}
 */
export function rosterFacts(cohorts) {
  if (cohorts.length === 0) throw new Error("the roster has no cohorts, so there is nothing to count");
  return {
    researchers: cohorts.reduce((n, c) => n + c.researchers.length, 0),
    cohorts: cohorts.length,
    since: Math.min(...cohorts.map((c) => c.year)),
  };
}

/** @param {unknown} value @returns {value is Record<string, unknown>} */
const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

/** @param {unknown} value */
const isPositiveInteger = (value) => typeof value === "number" && Number.isInteger(value) && value > 0;

/**
 * @param {unknown} photo
 * @param {RosterHost} host
 * @returns {Promise<string[]>}
 */
async function photoErrors(photo, host) {
  if (!isRecord(photo)) return ["photo is a mapping (src, width, height, alt) or null"];
  /** @type {string[]} */
  const errors = [];
  for (const key of Object.keys(photo)) {
    if (!PHOTO_FIELDS.includes(key)) errors.push(`photo.${key} is not a roster field; a photo carries ${PHOTO_FIELDS.join(", ")} and nothing else`);
  }
  const { src, width, height, alt } = photo;
  if (typeof src !== "string" || !PHOTO_SRC.test(src)) {
    errors.push(`photo.src is ${JSON.stringify(src)}; it is a .webp path under ${ROSTER_PHOTO_DIR}, such as ${ROSTER_PHOTO_DIR}example.webp`);
  } else if (!(await host.photo(src))) {
    errors.push(`photo.src ${src} is not in the repository (public${src}); the photograph is a static asset and is not uploaded here`);
  }
  if (!isPositiveInteger(width)) errors.push(`photo.width is ${JSON.stringify(width)}; it is the photograph's real width in pixels`);
  if (!isPositiveInteger(height)) errors.push(`photo.height is ${JSON.stringify(height)}; it is the photograph's real height in pixels`);
  if (typeof alt !== "string" || alt.trim() === "") {
    errors.push("photo.alt is required: the photographs are content, and alt text that is empty fails WCAG");
  } else if (alt !== alt.trim() || alt.length > ALT_MAX) {
    errors.push(`photo.alt is padded or longer than ${ALT_MAX} characters`);
  }
  return errors;
}

/**
 * @param {unknown} researchers
 * @returns {string[]}
 */
function researcherErrors(researchers) {
  if (!Array.isArray(researchers)) return ["researchers is a list of names (an empty list renders as 'Roster to be added')"];
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  researchers.forEach((name, i) => {
    const at = `researchers[${i}]`;
    if (typeof name !== "string" || name.trim() === "") {
      errors.push(`${at} is ${JSON.stringify(name)}; a name is a non-empty string`);
      return;
    }
    if (name !== name.trim() || /\s{2}|[\r\n\t]/.test(name)) errors.push(`${at} has stray whitespace; names are kept as given, on one line`);
    if (name.length > NAME_MAX) errors.push(`${at} is longer than ${NAME_MAX} characters`);
    if (seen.has(name)) errors.push(`${at} repeats a name already in this cohort`);
    seen.add(name);
  });
  return errors;
}

/**
 * Judges one file and, when it passes, builds the cohort. Every message the file has is returned, never the
 * first alone, so a writer fixes all of them at once.
 *
 * @param {{ slug: string, raw: string, host: RosterHost, pipeline: RosterPipeline, sourcePath?: string }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], cohort: Cohort, record: string, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compileCohort({ slug, raw, host, pipeline, sourcePath }) {
  /** @type {string[]} */
  const errors = pipeline
    .findWideDashes(raw)
    .map((hit) => `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`);
  if (!raw.startsWith("---")) errors.push("the file must start with a --- front matter block");

  let parsed;
  try {
    // An options object, even an empty one: gray-matter caches by input when it is omitted.
    parsed = matter(raw, {});
  } catch (error) {
    return { ok: false, errors: [...errors, `the front matter is not valid YAML: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`] };
  }
  const data = parsed.data;
  if (parsed.content.trim() !== "") errors.push("the body must be empty: a cohort is its front matter and nothing else");
  for (const key of Object.keys(data)) {
    if (!FIELDS.includes(key)) {
      errors.push(`${key} is not a roster field; a cohort carries ${FIELDS.join(", ")} and nothing else (no contact details, locations or other personal data)`);
    }
  }

  const { year, photo, researchers } = data;
  if (typeof year !== "number" || !Number.isInteger(year) || year < 2000 || year > 2099) {
    errors.push(`year is ${JSON.stringify(year)}; it is the cohort's four-digit year`);
  } else if (slug !== String(year)) {
    errors.push(`year is ${year}, but the file is ${rosterPath(slug)}: a cohort's file is named for its year (${year}.md)`);
  }
  if (!/^\d{4}$/.test(slug)) errors.push(`"${slug}" is not a cohort file key; the file is named for the year, such as 2025.md`);

  if (photo === undefined) errors.push("photo is required (a mapping, or null for a cohort with no photograph)");
  else if (photo !== null) errors.push(...(await photoErrors(photo, host)));
  errors.push(...researcherErrors(researchers));
  if (errors.length > 0) return { ok: false, errors };

  /** @type {Cohort} */
  const cohort = {
    year: /** @type {number} */ (year),
    photo: photo === null ? null : (({ src, width, height, alt }) => ({ src, width, height, alt }))(/** @type {CohortPhoto} */ (photo)),
    researchers: /** @type {string[]} */ (researchers),
  };
  return {
    ok: true,
    errors: [],
    cohort,
    record: JSON.stringify(cohort),
    sourcePath: sourcePath ?? rosterPath(slug),
    sourceBlobSha: await gitBlobSha(raw),
  };
}

/**
 * What only the whole set can say: the files are the roster, so an empty set is a fault, and two files
 * cannot be one year.
 *
 * @param {Cohort[]} cohorts
 * @returns {string[]}
 */
export function rosterSetErrors(cohorts) {
  /** @type {string[]} */
  const errors = [];
  if (cohorts.length === 0) errors.push(`${ROSTER_DIR} holds no cohort files; the roster cannot be empty`);
  const years = new Set();
  for (const { year } of cohorts) {
    if (years.has(year)) errors.push(`two files are the ${year} cohort`);
    years.add(year);
  }
  return errors;
}

